func (v *CrazyNesting) MarshalLogObject(enc zapcore.ObjectEncoder) (err error) {
	if v == nil {
		return nil
	}
	if v.StringField != nil {
		enc.AddString("string_field", *v.StringField)
	}
	if v.SetField != nil {
		err = multierr.Append(err, enc.AddArray("set_field", (_Set_Insanity_Zapper)(v.SetField)))
	}
	err = multierr.Append(err, enc.AddArray("list_field", (_List_Map_Set_I32_Map_I32_Set_List_Map_Insanity_String_Zapper)(v.ListField)))
	if v.BinaryField != nil {
		enc.AddString("binary_field", base64.StdEncoding.EncodeToString(v.BinaryField))
	}
	return err
}

func (_m *StepClient) Header() (metadata.MD, error) {
	ret := _m.Called()

	var r0 metadata.MD
	if rf, ok := ret.Get(0).(func() metadata.MD); ok {
		r0 = rf()
	} else {
		if ret.Get(0) != nil {
			r0 = ret.Get(0).(metadata.MD)
		}
	}

	var r1 error
	if rf, ok := ret.Get(1).(func() error); ok {
		r1 = rf()
	} else {
		r1 = ret.Error(1)
	}

	return r0, r1
}

func deriveCompare(this, that *MyStruct) int {
	if this == nil {
		if that == nil {
			return 0
		}
		return -1
	}
	if that == nil {
		return 1
	}
	if c := deriveCompare_(this.Int64, that.Int64); c != 0 {
		return c
	}
	if c := deriveCompare_1(this.StringPtr, that.StringPtr); c != 0 {
		return c
	}
	return 0
}

