func (ks *JavaServerSelector) PickServer(key string) (net.Addr, error) {
	if len(ks.addrs) == 0 {
		return nil, mc.ErrNoServers
	}

	if len(ks.addrs) == 1 {
		return ks.addrs[0], nil
	}

	h := hash(key)

	i := sort.Search(len(ks.ring), func(i int) bool {
		return ks.ring[i].hash >= h
	})

	if i == len(ks.ring) {
		i = 0
	}

	return ks.ring[i].addr, nil
}

