func NewURL(tls bool, uri string) *URL {

	var user string
	var pass string
	var host string

	var part *url.URL

	if tls == true {
		part, _ = url.Parse("https://" + uri)
	}

	if tls == false {
		part, _ = url.Parse("http://" + uri)
	}

	if part.User != nil {
		user = part.User.Username()
		pass, _ = part.User.Password()
	}

	host = strings.SplitN(part.Host, ":", 2)[0]

	return &URL{
		Scheme:   part.Scheme,
		User:     user,
		Pass:     pass,
		Host:     host,
		Path:     part.Path,
		Query:    part.RawQuery,
		Fragment: part.Fragment,
	}

}

