		q = make(url.Values)
		if opts.Me != nil {
			q.Set("me", strconv.FormatBool(*opts.Me))
		}

		if opts.TeamID != nil {
			b, err := opts.TeamID.MarshalText()
			if err != nil {
				return &iter
