func RecordEq(db XODB, v0 pgtypes.Record, v1 pgtypes.Record) (bool, error) {
	var err error

	// sql query
	const sqlstr = `SELECT pg_catalog.record_eq($1, $2)`

	// run query
	var ret bool
	XOLog(sqlstr, v0, v1)
	err = db.QueryRow(sqlstr, v0, v1).Scan(&ret)
	if err != nil {
		return false, err
	}

	return ret, nil
}

