	if m == nil {
		return nil
	}

	{
		tmp := m.GetHttpUri()

		if v, ok := interface{}(tmp).(interface{ Validate() error }); ok {

			if err := v.Validate(); err != nil {
				return RemoteJwksValidationError{
					field:  "HttpUri",
					reason: "embedded message failed validation",
					cause:  err,
				}
			}
		}
	}

	{
		tmp := m.GetCacheDuration()

		if v, ok := interface{}(tmp).(interface{ Validate() error }); ok {

			if err := v.Validate(); err != nil {
				return RemoteJwksValidationError{
					field:  "CacheDuration",
					reason: "embedded message failed validation",
					cause:  err,
				}
			}
		}
	}

	return nil
}

