func (m Mat2) Inv() Mat2 {
	det := m.Det()
	if FloatEqual(det, float32(0.0)) {
		return Mat2{}
	}

	retMat := Mat2{m[3], -m[1], -m[2], m[0]}

	return retMat.Mul(1 / det)
}

