}

func (r *DB) Begin() (err error) {
	if r.inTx > 0 {
		_, err = r.Exec(fmt.Sprintf("SAVEPOINT sp_%d", r.inTx))
	}
	if r.inTx == 0 {
		if r.ctx == nil {
			r.Log(func() {
				r.Tx, err = r.DB.Beginx()
			}, "BEGIN;")
		} else {
			r.Log(func() {
				r.Tx, err = r.DB.BeginTxx(r.ctx, r.TxOpts)
			}, "BEGIN; -- with context")
		}
	}
	if err != nil {
		return errors.WithStack(err)
	}

	r.inTx++
	return nil
}

func (d *NvidiaDevice) stats(ctx context.Context, stats chan<- *device.StatsResponse, interval time.Duration) {
	defer close(stats)

	if d.initErr != nil {
		if d.initErr.Error() != nvml.UnavailableLib.Error() {
			d.logger.Error("exiting stats due to problems with NVML loading", "error", d.initErr)
			stats <- device.NewStatsError(d.initErr)
		}

		return
	}

	// Create a timer that will fire immediately for the first detection
	ticker := time.NewTimer(0)

	for {
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
			ticker.Reset(interval)
		}

		d.writeStatsToChannel(stats, time.Now())
	}
}

