func (cons *SimpleConsumer) Configure(conf PluginConfigReader) {
	cons.id = conf.GetID()
	cons.Logger = conf.GetLogger()
	cons.runState = NewPluginRunState()
	cons.control = make(chan PluginControl, 1)

	numRoutines := conf.GetInt("ModulatorRoutines", 0)
	queueSize := conf.GetInt("ModulatorQueueSize", 1024)

	if numRoutines > 0 {
		cons.Logger.Debugf("Using %d modulator routines", numRoutines)
		cons.modulatorQueue = NewMessageQueue(int(queueSize))
		for i := 0; i < int(numRoutines); i++ {
			go cons.processQueue()
		}
		cons.enqueueMessage = cons.parallelEnqueue
	} else {
		cons.enqueueMessage = cons.directEnqueue
	}

	// Simple health check for the plugin state
	//   Path: "/<plugin_id>/pluginState"
	cons.AddHealthCheckAt("/pluginState", func() (code int, body string) {
		if cons.IsActive() {
			return thealthcheck.StatusOK, fmt.Sprintf("ACTIVE: %s", cons.runState.GetStateString())
		}
		return thealthcheck.StatusServiceUnavailable,
			fmt.Sprintf("NOT_ACTIVE: %s", cons.runState.GetStateString())
	})
}

func (f *File) Close() error {
	f.connsLock.Lock()
	defer f.connsLock.Unlock()

	if f.closed {
		return nil
	}

	err := f.closeAllConns()
	if err != nil {
		return err
	}

	if f.DumpStats {
		fetchedBytes := f.stats.fetchedBytes

		log.Printf("====== htfs stats for %s", f.name)
		log.Printf("= conns: %d total, %d expired, %d renews, wait %s", f.stats.connections, f.stats.expired, f.stats.renews, f.stats.connectionWait)
		size := f.size
		perc := 0.0
		percCached := 0.0
		if size != 0 {
			perc = float64(fetchedBytes) / float64(size) * 100.0
		}
		totalServedBytes := fetchedBytes
		percCached = float64(f.stats.cachedBytes) / float64(totalServedBytes) * 100.0

		log.Printf("= fetched: %s / %s (%.2f%%)", progress.FormatBytes(fetchedBytes), progress.FormatBytes(size), perc)
		log.Printf("= served from cache: %s (%.2f%% of all served bytes)", progress.FormatBytes(f.stats.cachedBytes), percCached)

		totalReads := f.stats.numCacheHits + f.stats.numCacheMiss
		if totalReads == 0 {
			totalReads = -1 // avoid NaN hit rate
		}
		hitRate := float64(f.stats.numCacheHits) / float64(totalReads) * 100.0
		log.Printf("= cache hit rate: %.2f%% (out of %d reads)", hitRate, totalReads)
		log.Printf("========================================")
	}

	f.closed = true

	return nil
}

