func RunInTransaction(db *sql.DB, f func(*sql.Tx) error) error {
	tx, err := db.Begin()
	if err != nil {
		return &TransactionError{nil, err}
	}
	err = f(tx)
	var txErr error
	if err == nil {
		txErr = tx.Commit()
	} else {
		txErr = tx.Rollback()
	}
	if err != nil || txErr != nil {
		return &TransactionError{err, txErr}
	}
	return nil
}

