func (m *memory) Objects(ctx context.Context, s *node.Node, p *predicate.Predicate, lo *storage.LookupOptions, objs chan<- *triple.Object) error {
	if objs == nil {
		return fmt.Errorf("cannot provide an empty channel")
	}

	sUUID := UUIDToByteString(s.UUID())
	pUUID := UUIDToByteString(p.PartialUUID())
	spIdx := sUUID + pUUID
	m.rwmu.RLock()
	defer m.rwmu.RUnlock()
	defer close(objs)

	if lo.LatestAnchor {
		lastTA := make(map[string]*time.Time)
		trps := make(map[string]*triple.Triple)
		for _, t := range m.idxSP[spIdx] {
			p := t.Predicate()
			ppUUID := p.PartialUUID().String()
			if p.Type() == predicate.Temporal {
				ta, err := p.TimeAnchor()
				if err != nil {
					return err
				}
				if lta := lastTA[ppUUID]; lta == nil || ta.Sub(*lta) > 0 {
					trps[ppUUID] = t
					lastTA[ppUUID] = ta
				}
			}
		}
		for _, trp := range trps {
			if trp != nil {
				objs <- trp.Object()
			}
		}
		return nil
	}
	ckr := newChecker(lo, p)
	for _, t := range m.idxSP[spIdx] {
		if ckr.CheckAndUpdate(t.Predicate()) {
			objs <- t.Object()
		}
	}
	return nil
}

func (h *Handler) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	defer func() {
		if err := recover(); err != nil {
			w.WriteHeader(http.StatusInternalServerError)
			stack := debug.Stack()
			msg := "PANIC: %s\n%s"
			h.logger.Printf(msg, err, stack)
			fmt.Fprintf(w, msg, err, stack)
		}
	}()

	t := time.Now()
	h.Handler.ServeHTTP(w, r)
	dif := time.Since(t)

	// Calculate per request StatsD metrics when the handler is fully configured.
	statsTags := make([]string, 0, 3)

	longQueryTime := h.api.LongQueryTime()
	if longQueryTime > 0 && dif > longQueryTime {
		h.logger.Printf("%s %s %v", r.Method, r.URL.String(), dif)
		statsTags = append(statsTags, "slow_query")
	}

	pathParts := strings.Split(r.URL.Path, "/")
	endpointName := strings.Join(pathParts, "_")

	if externalPrefixFlag[pathParts[1]] {
		statsTags = append(statsTags, "external")
	}

	// useragent tag identifies internal/external endpoints
	statsTags = append(statsTags, "useragent:"+r.UserAgent())
	stats := h.api.StatsWithTags(statsTags)
	if stats != nil {
		stats.Histogram("http."+endpointName, float64(dif), 0.1)
	}
}

