func normalizeEncodingDefinitions(defs []*design.EncodingDefinition) []*design.EncodingDefinition {
	// First splat all definitions so each only have one mime type
	var encs []*design.EncodingDefinition
	for _, enc := range defs {
		if len(enc.MIMETypes) == 1 {
			encs = append(encs, enc)
			continue
		}
		for _, m := range enc.MIMETypes {
			encs = append(encs, &design.EncodingDefinition{
				MIMETypes:   []string{m},
				PackagePath: enc.PackagePath,
				Function:    enc.Function,
				Encoder:     enc.Encoder,
			})
		}
	}

	// Next make sure all definitions have a package path
	for _, enc := range encs {
		if enc.PackagePath == "" {
			mt := enc.MIMETypes[0]
			enc.PackagePath = design.KnownEncoders[mt]
			idx := 0
			if !enc.Encoder {
				idx = 1
			}
			enc.Function = design.KnownEncoderFunctions[mt][idx]
		} else if enc.Function == "" {
			if enc.Encoder {
				enc.Function = "NewEncoder"
			} else {
				enc.Function = "NewDecoder"
			}
		}
	}

	// Regroup by package and function name
	byfn := make(map[string][]*design.EncodingDefinition)
	var first string
	for _, enc := range encs {
		key := enc.PackagePath + "#" + enc.Function
		if first == "" {
			first = key
		}
		if _, ok := byfn[key]; ok {
			byfn[key] = append(byfn[key], enc)
		} else {
			byfn[key] = []*design.EncodingDefinition{enc}
		}
	}

	// Reserialize into array keeping the first element identical since it's the default
	// encoder.
	return serialize(byfn, first)
}

func (l *lockServer) Lock(args *dsync.LockArgs, reply *bool) error {
	l.mutex.Lock()
	defer l.mutex.Unlock()
	_, *reply = l.lockMap[args.Resource]
	if !*reply { // No locks held on the given name, so claim write lock
		l.lockMap[args.Resource] = []lockRequesterInfo{
			{
				writer:        true,
				serverAddr:    args.ServerAddr,
				rpcPath:       args.ServiceEndpoint,
				uid:           args.UID,
				timestamp:     time.Now().UTC(),
				timeLastCheck: time.Now().UTC(),
			},
		}
	}
	*reply = !*reply // Negate *reply to return true when lock is granted or false otherwise
	return nil
}

func Run(
	path string,
	args []string,
	env []string,
	status io.Writer) (err error) {
	if status == nil {
		status = ioutil.Discard
	}

	// Set up the pipe that we will hand to the daemon.
	pipeR, pipeW, err := os.Pipe()
	if err != nil {
		err = fmt.Errorf("Pipe: %v", err)
		return
	}

	// Attempt to start the daemon process. If we encounter an error in so doing,
	// write it to the channel.
	startProcessErr := make(chan error, 1)
	go func() {
		defer pipeW.Close()
		err := startProcess(path, args, env, pipeW)
		if err != nil {
			startProcessErr <- err
		}
	}()

	// Read communication from the daemon from the pipe, writing nil into the
	// channel only if the startup succeeds.
	readFromProcessOutcome := make(chan error, 1)
	go func() {
		defer pipeR.Close()
		readFromProcessOutcome <- readFromProcess(pipeR, status)
	}()

	// Wait for a result from one of the above.
	select {
	case err = <-startProcessErr:
		err = fmt.Errorf("startProcess: %v", err)
		return

	case err = <-readFromProcessOutcome:
		if err == nil {
			// All is good.
			return
		}

		err = fmt.Errorf("readFromProcess: %v", err)
		return
	}
}

