func HexToDec(hexMask string, base int) (int, bool) {
	var number int = 0
	var i int
	for i = base; i < len(hexMask); i++ {
		if '0' <= hexMask[i] && hexMask[i] <= '9' {
			number *= 16
			number += int(hexMask[i] - '0')
		} else if 'a' <= hexMask[i] && hexMask[i] <= 'f' {
			number *= 16
			number += int(hexMask[i]-'a') + 10
		} else if 'A' <= hexMask[i] && hexMask[i] <= 'F' {
			number *= 16
			number += int(hexMask[i]-'A') + 10
		} else {
			break
		}
		if number >= 0xFFFFFF {
			return 0, false
		}
	}
	if i == base {
		return 0, false
	}
	return number, true
}

func (bk *Backend) AcquireLock(token string, ttl time.Duration) (err error) {
	bk.log.Debugf("AcquireLock(%s)", token)

	if err = legacy.ValidateLockTTL(ttl); err != nil {
		return trace.Wrap(err)
	}

	bucket := []string{locksBucket}
	for {
		// GetVal will clear TTL on a lock
		bk.GetVal(bucket, token)

		// CreateVal is atomic:
		err = bk.CreateVal(bucket, token, []byte{1}, ttl)
		if err == nil {
			break // success
		}
		if trace.IsAlreadyExists(err) { // locked? wait and repeat:
			bk.Clock().Sleep(250 * time.Millisecond)
			continue
		}
		return trace.ConvertSystemError(err)
	}

	return nil
}

