private void obtainQualityMarks() {
        int total = 0;
        for (int i = 0; i < this.qualityScoresArray.length; i++) {
            total += this.qualityScoresArray[i];
            this.maximumQuality = Math.max(this.qualityScoresArray[i], this.maximumQuality);
