private CatalogTable validatePartitionSpec(ObjectPath tablePath, CatalogPartitionSpec partitionSpec)
		throws TableNotExistException, TableNotPartitionedException, PartitionSpecInvalidException {

		CatalogTable table = validatePartitionedTable(tablePath);

		List<String> partitionKeys = table.getPartitionKeys();
		Map<String, String> spec = partitionSpec.getPartitionSpec();

		// The size of partition spec should not exceed the size of partition keys
		if (partitionKeys.size() < spec.size()) {
			throw new PartitionSpecInvalidException(catalogName, partitionKeys, tablePath, partitionSpec);
		} else {
			int size = spec.size();

			// PartitionSpec should contain the first 'size' number of keys in partition key list
			for (int i = 0; i < size; i++) {
				if (!spec.containsKey(partitionKeys.get(i))) {
					throw new PartitionSpecInvalidException(catalogName, partitionKeys, tablePath, partitionSpec);
				}
			}
		}

		return table;
	}

public void shutdownSlee() throws InvalidStateException {
		if (sleeState != SleeState.STOPPED) {
			throw new InvalidStateException("slee in "+sleeState+" state");
		}
		// slee shutdown
		beforeModulesShutdown();
		for (Iterator<SleeContainerModule> i = modules
				.descendingIterator(); i.hasNext();) {
			i.next().sleeShutdown();
		}
		afterModulesShutdown();
		sleeState = null;
	}

public static DataChecksum newDataChecksum( int type, int bytesPerChecksum, Checksum sum ) {
    if ( bytesPerChecksum <= 0 ) {
      return null;
    }

    int checksumSize = getChecksumSizeByType(type);

    switch ( type ) {
    case CHECKSUM_NULL :
      return new DataChecksum( CHECKSUM_NULL, new ChecksumNull(), 
          checksumSize, bytesPerChecksum );
    case CHECKSUM_CRC32 :
      return new DataChecksum( CHECKSUM_CRC32, sum, 
          checksumSize, bytesPerChecksum );
    default:
      return null;  
    }
  }

