            StringBuilder builder = new StringBuilder(100);
            builder.append("Resolved dependencies:").append(NEW_LINE);
            map.forEach((k, v) -> {
                builder.append(k).append(NEW_LINE);
                v.forEach(e -> builder.append("\t").append(e).append(NEW_LINE));
