public static <K, V> void fillValues(Map<K, V> map, 
        Iterable<? extends V> values)
    {
        Iterator<? extends V> iterator = values.iterator();
        for (K k : map.keySet())
        {
            if (!iterator.hasNext())
            {
                break;
            }
            V value = iterator.next();
            map.put(k, value);
        }
    }

