            throw new SdkClientException("Invalid argument passed to marshall(...)");
        }

        try {
            protocolMarshaller.marshall(nodeToNodeEncryptionOptionsStatus.getOptions(), OPTIONS_BINDING);
            protocolMarshaller.marshall(nodeToNodeEncryptionOptionsStatus.getStatus(), STATUS_BINDING);
        } catch (Exception e) {
            throw new SdkClientException("Unable to marshall request to JSON: " + e.getMessage(), e);
        }
    }

