public static Bundle arguments(Fragment frag) {
        Bundle args = frag.getArguments();
        if (args == null) {
            if (!frag.isAdded()) {
                args = new Bundle();
                try {
                    frag.setArguments(args);
                } catch (IllegalStateException e) { // "attached" but not yet "added"
                    args = EMPTY;
                }
            } else {
                args = EMPTY;
            }
        }
        return args;
    }

