public static int FVN32hash(byte[] bytes) {
        long hash = FNV_BASIS;
        for (int i = 0; i < bytes.length; i++) {
            hash ^= 0xFF & bytes[i];
            hash *= FNV_PRIME_32;
        }
        return (int) hash;
    }

