private List<GeoLocation> decodePolyLine(String poly) {
		int len = poly.length();
		int index = 0;
		List<GeoLocation> decoded = new ArrayList<>();
		int lat = 0;
		int lng = 0;

		while (index < len) {
			int b;
			int shift = 0;
			int result = 0;
			do {
				b = poly.charAt(index++) - 63;
				result |= (b & 0x1f) << shift;
				shift += 5;
			} while (b >= 0x20);
			int dlat = (result & 1) != 0 ? ~(result >> 1) : (result >> 1);
			lat += dlat;

			shift = 0;
			result = 0;
			do {
				b = poly.charAt(index++) - 63;
				result |= (b & 0x1f) << shift;
				shift += 5;
			} while (b >= 0x20);
			int dlng = (result & 1) != 0 ? ~(result >> 1) : (result >> 1);
			lng += dlng;

			decoded.add(new GeoLocation(lat / 1E5, lng / 1E5));
		}

		return decoded;
	}

private int getReturnParam() {
    // look for [retval] attribute
        for (int i = 0; i < params.length; i++) {
      if (params[i].isRetval()) {
        return i;
      }
    }

    // sometimes a COM method has only one [out] param.
    // treat that as the return value.
    // this is seen frequently in MSHTML (see IHTMLChangeLog, for example)
    int outIdx = -1;
    for (int i = 0; i < params.length; i++) {
      if (params[i].isOut() && !params[i].isIn()) {
        if (outIdx == -1) {
          outIdx = i;
        } else {
          return -1; // more than one out. no return value
        }
      }
    }
    return outIdx;
  }

