protected void log(String aLevel, Object obj, Throwable t)
    {
        buffer.append(BRAKE_OPEN).append(getName()).append(BRAKE_CLOSE).append(aLevel);
        if (obj != null && obj instanceof Throwable)
        {
            try
            {
                buffer.append(((Throwable) obj).getMessage()).append(EOL);
                ((Throwable) obj).printStackTrace();
            }
            catch (Throwable ignored)
            {
                /*logging should be failsafe*/
            }
        }
        else
        {
            try
            {
                buffer.append(obj).append(EOL);
            }
            catch(Exception e)
            {
                // ignore
            }
        }

        if (t != null)
        {
            try
            {
                buffer.append(t.getMessage()).append(EOL);
                buffer.append(ExceptionUtils.getFullStackTrace(t)).append(EOL);
            }
            catch (Throwable ignored)
            {
                /*logging should be failsafe*/
            }
        }
        if(!errorLog && (aLevel.equals(STR_ERROR) || aLevel.equals(STR_FATAL)))
        {
            errorLog = true;
        }
    }

@Override
    public void createPropertyValues(URI graphUri, List<Triplet<URI, URI, Object>> subjectPropertyValues) throws SalException {

        // Validate the input
        if (graphUri == null || !graphStoreManager.containsGraph(graphUri)) {
            // The graph cannot be updated
            logger.error("The graph to update does not exist: {}", graphUri);
            throw new SalException("The graph to update does not exist: " + graphUri.toASCIIString());
        }

        if (subjectPropertyValues == null || subjectPropertyValues.isEmpty()) {
            // Nothing to update
            logger.error("Nothing to update (?). Skipping.");
            return;
        }

        OntModel model = ModelFactory.createOntologyModel();

        URI subject = null;
        URI property;
        Object value;
        RDFNode object;
        Statement triple;

        // Loop over every subject-property-object entry
        for (Triplet<URI, URI, Object> triplet : subjectPropertyValues) {
            subject = triplet.getSubject();
            property = triplet.getProperty();
            value = triplet.getObject();

            // Create the proper object for the update
            if (value instanceof URI) {
                object = model.createResource(((URI) value).toASCIIString());
                if (property.toASCIIString().equals(SAWSDL.modelReference.getURI())) {
                    URI modelUri;
                    try {
                        modelUri = URIUtil.getNameSpace((URI) value);
                        if (!graphStoreManager.containsGraph(modelUri)) {
                            if (graphStoreManager.fetchAndStore(modelUri)) {
                                getEventBus().post(new OntologyCreatedEvent(new Date(), modelUri));
                            }
                        }
                    } catch (URISyntaxException e) {
                        logger.warn("Ignoring modelReference URI. URI syntax exception: {}", value );
                        e.printStackTrace();
                    }
                }
            } else {
                object = model.createTypedLiteral(value);
            }

            // Create the statement
            triple = model.createStatement(model.createResource(subject.toASCIIString()), model.createProperty(property.toASCIIString()), object);
            model.add(triple);
        }

        if (logger.isDebugEnabled()) {
            // Print out the model
            String syntax = "TURTLE";
            StringWriter out = new StringWriter();
            model.write(out, syntax);
            String result = out.toString();
            logger.debug("Uploading model: {}", result);
        }

        // All spo have been added to the model now. Update the graph
        graphStoreManager.addModelToGraph(graphUri, model);
        if (subject != null) {
            propertyValueCache.remove(subject.toASCIIString());
        }
    }

