public static List<TypeDeclaration> mergeTypes(List<TypeDeclaration> one, List<TypeDeclaration> two) throws Exception {
        List<TypeDeclaration> result = new ArrayList<>();

        for (TypeDeclaration outer : one) {

            boolean found = false;
            for (TypeDeclaration inner : two) {

                if (outer.getName().equals(inner.getName())) {
                    TypeDeclaration merged = mergeType(outer, inner);
                    result.add(merged);
                    found = true;
                }
            }

            if (!found) {
                result.add(outer);
                LOG.info("add {} --> {}", outer.getClass().getSimpleName(), outer.getName());
            }
        }
        return result;
    }

public int disconnect(int vertex) {
        int removed = 0;
        if (inEdges.remove(vertex))
            removed++;
        if (outEdges.remove(vertex))
            removed++;
        return removed;
    }

public static Object unboxAll(Class<?> type, Object src, int srcPos, int len) {
        switch (tId(type)) {
            case I_BOOLEAN:     return unboxBooleans(src, srcPos, len);
            case I_BYTE:        return unboxBytes(src, srcPos, len);
            case I_CHARACTER:   return unboxCharacters(src, srcPos, len);
            case I_DOUBLE:      return unboxDoubles(src, srcPos, len);
            case I_FLOAT:       return unboxFloats(src, srcPos, len);
            case I_INTEGER:     return unboxIntegers(src, srcPos, len);
            case I_LONG:        return unboxLongs(src, srcPos, len);
            case I_SHORT:       return unboxShorts(src, srcPos, len);
        }
        throw new IllegalArgumentException("No primitive/box: " + type);
    }

public static ImmutableEndpoint getImmutableEndpoint(MuleContext muleContext, String endpointName) throws IOException {
		ImmutableEndpoint endpoint = null;

		Object o = muleContext.getRegistry().lookupObject(endpointName);
		if (o instanceof ImmutableEndpoint) {
			// For Inbound and Outbound Endpoints
			endpoint = (ImmutableEndpoint) o;

		} else if (o instanceof EndpointBuilder) {
			// For Endpoint-references
			EndpointBuilder eb = (EndpointBuilder) o;
			try {
				endpoint = eb.buildInboundEndpoint();
			} catch (Exception e) {
				throw new IOException(e.getMessage());
			}
		}
		return endpoint;
	}

