@Override
	public synchronized void removeEngine(Engine engine) {

        if( log.isDebugEnabled() )
            log.debug("Removing engine (" + engine.getInfo() + ")");

        // Is the specified Engine actually defined?
        int j = -1;
        for (int i = 0; i < engines.length; i++) {
            if (engine == engines[i]) {
                j = i;
                break;
            }
        }
        if (j < 0)
            return;

        // Remove any Connector that is using this Engine
        if( log.isDebugEnabled() )
            log.debug(" Removing related Containers");
        while (true) {
            int n = -1;
            Connector[] connectors = service.findConnectors();
            for (int i = 0; i < connectors.length; i++) {
                if (connectors[i].getService().getContainer() == (Container) engine) {
                    n = i;
                    break;
                }
            }
            if (n < 0)
                break;
            service.removeConnector(connectors[n]);
        }

        // Stop this Engine if necessary
        if (engine instanceof Lifecycle) {
            if( log.isDebugEnabled() )
                log.debug(" Stopping this Engine");
            try {
                ((Lifecycle) engine).stop();
            } catch (LifecycleException e) {
                log.error("Engine.stop", e);
            }
        }

        // Remove this Engine from our set of defined Engines
        if( log.isDebugEnabled() )
            log.debug(" Removing this Engine");
        int k = 0;
        Engine results[] = new Engine[engines.length - 1];
        for (int i = 0; i < engines.length; i++) {
            if (i != j)
                results[k++] = engines[i];
        }
        engines = results;

    }

public static void pushExportBuffer(
            int partitionId,
            String tableName,
            long startSequenceNumber,
            long committedSequenceNumber,
            long tupleCount,
            long uniqueId,
            long genId,
            long bufferPtr,
            ByteBuffer buffer) {
        //For validating that the memory is released
        if (bufferPtr != 0) DBBPool.registerUnsafeMemory(bufferPtr);
        ExportManager instance = instance();
        try {
            ExportGeneration generation = instance.m_generation.get();
            if (generation == null) {
                if (buffer != null) {
                    DBBPool.wrapBB(buffer).discard();
                }
                return;
            }
            generation.pushExportBuffer(partitionId, tableName,
                    startSequenceNumber, committedSequenceNumber,
                    (int)tupleCount, uniqueId, genId, buffer);
        } catch (Exception e) {
            //Don't let anything take down the execution site thread
            exportLog.error("Error pushing export buffer", e);
        }
    }

public void paint(Graphics g) 
    {
        FontMetrics fm = this.getFontMetrics(this.getFont());

        Insets i = this.getInsets();

        viewRect.x = i.left;
        viewRect.y = i.top;
        viewRect.width = this.getWidth() - (i.right + viewRect.x);
        viewRect.height = this.getHeight() - (i.bottom + viewRect.y);

        textRect.x = textRect.y = textRect.width = textRect.height = 0;
        iconRect.x = iconRect.y = iconRect.width = iconRect.height = 0;

        Font f = this.getFont();
        g.setFont(f);

        // layout the text and icon
        String text = SwingUtilities.layoutCompoundLabel(
            this, fm, this.getText(), this.getIcon(), 
            this.getVerticalAlignment(), this.getHorizontalAlignment(),
            this.getVerticalTextPosition(), this.getHorizontalTextPosition(),
            viewRect, iconRect, textRect, 
	    this.getText() == null ? 0 : this.getIconTextGap());

        // Paint the Icon
        if(this.getIcon() != null) { 
            this.getIcon().paintIcon(this, g, iconRect.x, iconRect.y);;
        }

        if (text != null && !text.equals(""))
        {
            g.setColor(this.getForeground());
            int mnemonicIndex = this.getDisplayedMnemonicIndex();
            BasicGraphicsUtils.drawStringUnderlineCharAt(g, text, mnemonicIndex, textRect.x, textRect.y + fm.getAscent());

            if (m_bUnderlined)
            {   // Draw the underline if underlined
                Color oldColor = g.getColor();
                g.setColor(Color.blue);
                g.drawLine(textRect.x, textRect.y + fm.getAscent(), textRect.x + textRect.width, textRect.y + fm.getAscent());
                g.setColor(oldColor);
            }
        }
    }

