public CalendarWeek plus(Years<Weekcycle> years) {

        if (years.isEmpty()) {
            return this;
        }

        int y = MathUtils.safeAdd(this.year, years.getAmount());
        int effectiveWeek = this.week;

        if ((this.week == 53) && (maximumOfWeek(y) < 53)) {
            effectiveWeek = 52;
        }

        return CalendarWeek.of(y, effectiveWeek);

    }

public boolean isValid(String nonce) {

        // Remove nonce, verifying whether it was present at all
        Long expires = nonces.remove(nonce);
        if (expires == null)
            return false;

        // Nonce is only valid if it hasn't expired
        return expires > System.currentTimeMillis();

    }

