private static byte[] poisonBytes(byte[] bytesToPoisonParam) {
        if (bytesToPoisonParam == null) {
            return null;
        }

        byte[] returnVal = new byte[bytesToPoisonParam.length];

        for (int index = 0; index < bytesToPoisonParam.length; index++) {
