public boolean toFail()
  {
    LifecycleState state;

    synchronized (this) {
      state = _state;

      if (state.isAfterDestroying()) {
        return false;
      }

      _state = FAILED;

      _lastChangeTime = CurrentTime.currentTime();
    }

    if (_log != null && _log.isLoggable(_level))
      _log.log(_level, "fail " + _name);

    notifyListeners(state, FAILED);

    _failCount++;

    return true;
  }

