public static <T> T newInstanceIfPossible(Class<T> beanClass) {
		Assert.notNull(beanClass);
		try {
			return newInstance(beanClass);
		} catch (Exception e) {
			// ignore
			// 默认构造不存在的情况下查找其它构造
		}

		final Constructor<T>[] constructors = getConstructors(beanClass);
		Class<?>[] parameterTypes;
		for (Constructor<T> constructor : constructors) {
			parameterTypes = constructor.getParameterTypes();
			if (0 == parameterTypes.length) {
				continue;
			}
			constructor.setAccessible(true);
			try {
				return constructor.newInstance(ClassUtil.getDefaultValues(parameterTypes));
			} catch (Exception e) {
				// 构造出错时继续尝试下一种构造方式
				continue;
			}
		}
		return null;
	}

@Override
	public OutputStream getResourceAsOutputStream(String resourceName) throws IOException {

		// Create directories if needed
		String generatedFilePath = resourceName.substring(workingDir.length());
		if (!FileNameUtils.isExtension(generatedFilePath, JawrConstant.CSS_TYPE)
				&& binaryGeneratorRegistry.isGeneratedBinaryResource(generatedFilePath)) {
			// for generated image put it in the generated Image directory
			generatedFilePath = workingDir + JawrConstant.SPRITE_GENERATED_IMG_DIR
					+ generatedFilePath.replace(':', '/');
		} else if (cssGeneratorRegistry.isPathGenerated(generatedFilePath)) { // Rename
																				// resource
																				// for
																				// For
																				// generated
																				// CSS
			generatedFilePath = workingDir + JawrConstant.SPRITE_GENERATED_CSS_DIR
					+ generatedFilePath.replace(':', '/');
		} else {
			generatedFilePath = resourceName;
		}

		final File parentFile = new File(generatedFilePath).getParentFile();
		if (!parentFile.exists()) {
			if (!parentFile.mkdirs()) {
				throw new IOException("Unable to create the directory : " + parentFile.getPath());
			}
		}

		File file = new File(generatedFilePath);
		try {
			file = file.getCanonicalFile();
		} catch (final IOException e) {
			file = file.getAbsoluteFile();
		}

		return new FileOutputStream(file);
	}

