public CharSequence rewriteHtml(CharSequence input, String requestUrl, String baseUrlParam, String visibleBaseUrl,
            boolean absolute) {
        StringBuffer result = new StringBuffer(input.length());
        Matcher m = URL_PATTERN.matcher(input);
        while (m.find()) {
            String url = input.subSequence(m.start(3) + 1, m.end(3) - 1).toString();
            String tag = m.group(0);
            String quote = input.subSequence(m.end(3) - 1, m.end(3)).toString();

            // Browsers tolerate urls with white spaces before or after
            String trimmedUrl = StringUtils.trim(url);

            String rewrittenUrl = url;

            trimmedUrl = unescapeHtml(trimmedUrl);

            if (trimmedUrl.isEmpty()) {
                LOG.debug("empty url kept unchanged");
            } else if (trimmedUrl.startsWith("#")) {
                LOG.debug("anchor url kept unchanged: [{}]", url);
            } else if (JAVASCRIPT_CONCATENATION_PATTERN.matcher(trimmedUrl).find()) {
                LOG.debug("url in javascript kept unchanged: [{}]", url);
            } else if (m.group(2).equalsIgnoreCase("content")) {
                if (META_REFRESH_PATTERN.matcher(tag).find()) {
                    rewrittenUrl = rewriteRefresh(trimmedUrl, requestUrl, baseUrlParam, visibleBaseUrl);
                    rewrittenUrl = escapeHtml(rewrittenUrl);
                    LOG.debug("refresh url [{}] rewritten [{}]", url, rewrittenUrl);
                } else {
                    LOG.debug("content attribute kept unchanged: [{}]", url);
                }
            } else {
                rewrittenUrl = rewriteUrl(trimmedUrl, requestUrl, baseUrlParam, visibleBaseUrl, absolute);
                rewrittenUrl = escapeHtml(rewrittenUrl);
                LOG.debug("url [{}] rewritten [{}]", url, rewrittenUrl);
            }

            m.appendReplacement(result, ""); // Copy what is between the previous match and the current match
            result.append("<");
            result.append(m.group(1));
            result.append(m.group(2));
            result.append("=");
            result.append(quote);
            result.append(rewrittenUrl);
            result.append(quote);
            if (m.groupCount() > 3) {
                result.append(m.group(4));
            }
            result.append(">");
        }

        m.appendTail(result); // Copy the reminder of the input

        return result;
    }

protected AppendRequest buildAppendEmptyRequest(RaftMemberContext member) {
    final RaftLogReader reader = member.getLogReader();

    // Read the previous entry from the reader.
    // The reader can be null for RESERVE members.
    Indexed<RaftLogEntry> prevEntry = reader != null ? reader.getCurrentEntry() : null;

    DefaultRaftMember leader = raft.getLeader();
    return AppendRequest.builder()
        .withTerm(raft.getTerm())
        .withLeader(leader != null ? leader.memberId() : null)
        .withPrevLogIndex(prevEntry != null ? prevEntry.index() : reader != null ? reader.getFirstIndex() - 1 : 0)
        .withPrevLogTerm(prevEntry != null ? prevEntry.entry().term() : 0)
        .withEntries(Collections.emptyList())
        .withCommitIndex(raft.getCommitIndex())
        .build();
  }

public SpecNode getClosestSpecNodeByTargetId(final String targetId, final SpecNode callerNode, final boolean checkParentNode) {
        /*
         * Check this level to see if the topic exists
         */
        final List<Node> children = getChildNodes();
        for (final Node childNode : children) {
            if (childNode instanceof SpecNode) {
                final SpecNode specNode = (SpecNode) childNode;
                if (specNode.getTargetId() != null && specNode.getTargetId().equals(targetId)) {
                    return specNode;
                }
            }
        }

        /*
         * If we get to this stage, then the topic wasn't directly at this level. So we should try this levels, child levels
         * first.
         */
        final List<Level> childLevels = getChildLevels();
        for (final Level childLevel : childLevels) {
            if (childLevel == callerNode) {
                continue;
            } else {
                final SpecNode childLevelNode = childLevel.getClosestSpecNodeByTargetId(targetId, callerNode, false);
                if (childLevelNode != null) {
                    return childLevelNode;
                }
            }
        }

        /*
         * If we still haven't found the closest node then check this nodes parents.
         */
        if (getParent() != null && checkParentNode) {
            return getParent().getClosestSpecNodeByTargetId(targetId, this, checkParentNode);
        }

        return null;
    }

