            protocolMarshaller.marshall(boundingBox.getHeight(), HEIGHT_BINDING);
            protocolMarshaller.marshall(boundingBox.getLeft(), LEFT_BINDING);
            protocolMarshaller.marshall(boundingBox.getTop(), TOP_BINDING);
