function fc(fn, autorun, dimensions) {
  document.body.style.margin = "0px";
  document.body.style.padding = "0px";

  var canvas = document.createElement('canvas');
  document.body.appendChild(canvas);
  canvas.style.position = 'absolute';
  canvas.style.left = '0px';
  canvas.style.top = '0px';

  var ctx;
  dimensions = dimensions || 2;

  if (dimensions === 2) {
    ctx = patchGetContext(canvas.getContext('2d'))
  } else if (dimensions === 3) {
    ctx = canvas.getContext('webgl') || canvas.getContext('experimental-webgl');
  }

  if (!ctx) {
    return;
  }

  var last = performanceNow(), request;

  function requestFrame() {
    if (request === null) {
      request = requestAnimationFrame(tick);
    }
  }

  function tick() {
    request = null;
    var time = performanceNow();
    var delta = time-last;
    last = time;

    ctx.reset();

    dimensions === 2 && ctx.save();

    fn && fn.call(ctx, delta);

    dimensions === 2 && ctx.restore();
    if (autorun) {
      requestFrame();
    }
  }

  if (dimensions === 2) {
    ctx.reset = function fc_reset() {
      canvas.width = 0;
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
    };

    ctx.clear = function fc_clear(color) {
      var orig = ctx.fillStyle;
      ctx.fillStyle = color || "#223";
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      ctx.fillStyle = orig;
    };
  } else {
    ctx.reset = function fc_reset() {
      if (canvas.width !== window.innerWidth) {
        canvas.width = window.innerWidth;
      }

      if (canvas.height !== window.innerHeight) {
        canvas.height = window.innerHeight;
      }
    }
  }

  setTimeout(tick, 0);

  ctx.dirty = function fc_dirty() {
    last = performanceNow();
    requestFrame();
  };

  ctx.stop = function fc_stop() {
    autorun = false;
    request && cancelAnimationFrame(request);
    request = null;
  };

  ctx.start = function fc_start() {
    autorun = true;
    requestFrame();
  };

  (window.attachEvent || window.addEventListener)('resize', ctx.dirty);

  // resize to fullscreen immediately
  ctx.reset();

  ctx.canvas = canvas;
  return ctx;
}

async function rmdir(dir) {
    let stats = await stat(dir);

    // 判断文件存在
    if (stats) {

        // 处理文件夹
        if (stats.isDirectory()) {
            let files = await local.readdir(dir);

            // 依次移除子文件
            await Promise.all(
                files.map(file => rmdir(path.resolve(dir, file)))
            );

            // 移除空目录
            return await local.rmdir(dir);
        }

        // 移除文件
        await local.unlink(dir);
    }
}

