	var content = fc.replace(reg_comment, '').replace(/^[\s\r\n]+/, ''),
		i = 0, len = content.length,
		buf = '', //压缩结果buffer
		lc = '', //前一个字符
		c;
	for (; i < len; i++) {
		c = content[i];
		if (c==='\r' || c==='\n') {
			continue;
		}
		if (c===' ' || c==='\t') {
			if (reg_scs.test(lc)) {
				continue;
			}
			buf += lc;
			lc = ' ';
			continue;
		} else if (reg_scs.test(c)) {
			if (lc===' ' || (c==='}' && lc===';')) {
				lc = c;
				continue;
			}
		}
		buf += lc;
		lc = c;
	}

	return buf + lc;
}

