function runScript(exists, file, param, response) {
	console.log(TacitServer.configs.server_prefix + " - runScript called");
	if(!exists) return sendError(404, 'File not found', response);
	var command = '';
	var extension = file.split('.').pop();
	switch(extension) {
	case 'php':
		command = 'php';
		break;
	case 'js':
		command = 'node';
		break;
	default:
		// nothing
	}
	runner.exec(command + " " + file + " " + param,
	function(err, stdout, stderr) {
		sendData(err, stdout, stderr, response);
	}
	);
}

function initialize (name, provider, config) {
  var strategy
  var protocol = provider.protocol

  // try to load an officially supported provider
  try {
    strategy = require(path.join(__dirname, protocol))
  } catch (e) {}

  // try to load a custom provider from the deployment repository
  try {
    strategy = require(path.join(cwd, 'protocols', protocol))
  } catch (e) {
    if (!strategy) {
      throw new Error("Can't find custom protocol: " + protocol)
    }
  }

  provider.id = name
  return strategy.initialize(provider, config)
}

