function contoursTransform(contours, transforms) {
        if (!contours || !contours.length || !transforms || !transforms.length) {
            return contours;
        }

        var matrix = [1, 0, 0, 1, 0, 0];
        for (var i = 0, l = transforms.length; i < l; i++) {
            var transform = transforms[i];
            var params = transform.params;
            switch (transform.name) {
                case 'translate':
                    matrix = matrixUtil.mul(matrix, [1, 0, 0, 1, params[0], params[1]]);
                    break;
                case 'scale':
                    matrix = matrixUtil.mul(matrix, [params[0], 0, 0, params[1], 0, 0]);
                    break;
                case 'matrix':
                    matrix = matrixUtil.mul(matrix,
                        [params[0], params[1], params[2], params[3], params[4], params[5]]);
                    break;
                case 'rotate':
                    var radian = params[0] * Math.PI / 180;
                    if (params.length > 1) {

                        matrix = matrixUtil.multiply(
                            matrix,
                            [1, 0, 0, 1, -params[1], -params[2]],
                            [Math.cos(radian), Math.sin(radian), -Math.sin(radian), Math.cos(radian), 0, 0],
                            [1, 0, 0, 1, params[1], params[2]]
                        );
                    }
                    else {
                        matrix = matrixUtil.mul(
                            matrix, [Math.cos(radian), Math.sin(radian), -Math.sin(radian), Math.cos(radian), 0, 0]);
                    }
                    break;
                case 'skewX':
                    matrix = matrixUtil.mul(matrix,
                        [1, 0, Math.tan(params[0] * Math.PI / 180), 1, 0, 0]);
                    break;
                case 'skewY':
                    matrix = matrixUtil.mul(matrix,
                        [1, Math.tan(params[0] * Math.PI / 180), 0, 1, 0, 0]);
                    break;
            }
        }

        contours.forEach(function (p) {
            pathTransform(p, matrix[0], matrix[1], matrix[2], matrix[3], matrix[4], matrix[5]);
        });

        return contours;
    }

function partitionHandlers(oldState, newState) {
    var oldHandlers = oldState.handlerInfos;
    var newHandlers = newState.handlerInfos;

    var handlers = {
      updatedContext: [],
      exited: [],
      entered: [],
      unchanged: []
    };

    var handlerChanged,
        contextChanged = false,
        i,
        l;

    for (i = 0, l = newHandlers.length; i < l; i++) {
      var oldHandler = oldHandlers[i],
          newHandler = newHandlers[i];

      if (!oldHandler || oldHandler.handler !== newHandler.handler) {
        handlerChanged = true;
      }

      if (handlerChanged) {
        handlers.entered.push(newHandler);
        if (oldHandler) {
          handlers.exited.unshift(oldHandler);
        }
      } else if (contextChanged || oldHandler.context !== newHandler.context) {
        contextChanged = true;
        handlers.updatedContext.push(newHandler);
      } else {
        handlers.unchanged.push(oldHandler);
      }
    }

    for (i = newHandlers.length, l = oldHandlers.length; i < l; i++) {
      handlers.exited.unshift(oldHandlers[i]);
    }

    handlers.reset = handlers.updatedContext.slice();
    handlers.reset.reverse();

    return handlers;
  }

function pathParser(root, extname, subPath, paths) {
  var dirPath = path.resolve(subPath || root);
  var files;
  paths = paths || {};

  try {
    files = fs.readdirSync(dirPath);
  } catch(e) {
    files = [];
  }
  files.forEach(function(file) {
    file = path.join(dirPath, '/', file);
    if (fs.statSync(file).isFile()) {
      if (~extname.split('|').indexOf(path.extname(file).substr(1))) {
        var rootPath = '^' + path.join(path.resolve(root), '/');
        rootPath = rootPath.replace(/\\/g, '\\\\') + '(.*)\.(' + extname + ')$';
        paths[file.match(new RegExp(rootPath))[1].toLowerCase()] = file;
      }
    } else if (fs.statSync(file).isDirectory()) {
      pathParser(root, extname, file, paths);
    }
  });
  return paths;
}

