function rename(filepath, transformer) {
      var result;
      /*
        Return a file object

        {
          dirname
          basename
          extname
          origin
        }
      */
      var fileObj = parse(filepath);

      if (!transformer) {
        result = stringify(fileObj);
        debug('transform to %s with no transformer', result);
        return result;
      }

      /*
        transformed object

        {
          dirname
          prefix
          basename
          suffix
          extname
        }
