	if ( len !== b.length ) {
		throw new Error( 'hamming()::invalid input arguments. Sequences must be the same length.' );
	}
	d = 0;
	if ( clbk ) {
		for ( i = 0; i < len; i++ ) {
			if ( clbk( a[i], i, 0 ) !== clbk( b[i], i, 1 ) ) {
				d += 1;
			}
		}
