            speed = (metas['speed'][0] + Math.random() * metas['speed'][1]);
            sx = speed * Math.cos(this._a);
            sy = -speed * Math.sin(this._a);
            this._d = new C2D.Vector(sx, sy); //绑定一个速度实例
            this._m = metas;
        }

