function Config(options) {
  var useConfig;

  options = options || {};

  this.cache = {};
  this.parser = options.parser;

  this.useNplintrc = (options.useNplintrc !== false);
  this.useNplintignore = (options.useNplintignore !== false);

  useConfig = options.configFile;
  this.options = options;

  if (useConfig) {
    if (isResolvable(useConfig) || isResolvable('nplint-config-' + useConfig) || useConfig.charAt(0) === '@') {
      this.useSpecificConfig = loadConfig(useConfig);
    } else {
      this.useSpecificConfig = loadConfig(path.resolve(process.cwd(), useConfig));
    }
  }
}

function isMemberExpOf(node, objectName, {maxLength = Number.MAX_VALUE, allowComputed} = {}) {
    if (objectName) {
        let curr = node
        let depth = maxLength
        while (curr && depth) {
            if (allowComputed || isPropAccess(curr)) {
                if (curr.type === 'MemberExpression' && curr.object.name === objectName) {
                    return true
                }
                curr = curr.object
                depth--
            } else {
                return false
            }
        }
    }
}

