function encodePrimitiveDate( encoder, object ) {

	// We have a date primitive
	encoder.stream8.write( pack1b( PRIM_OP.OBJECT | OBJ_OP.PRIMITIVE | OBJ_PRIM.DATE ) );

	// Save date and timezone
	encoder.stream64.write( pack8f( Number(object) ) );
	encoder.stream16.write( pack1b( object.getTimezoneOffset() / 10, true ) );

}

function getArc(rx, ry, angle, largeArc, sweep, p0, p1) {
            var result = a2c(p0.x, p0.y, p1.x, p1.y, largeArc, sweep, rx, ry, angle);
            var path = [];

            if (result.length) {
                path.push({
                    x: result[0][0],
                    y: result[0][1],
                    onCurve: true
                });

                // 将三次曲线转换成二次曲线
                result.forEach(function (c, index) {
                    var q2Array = bezierCubic2Q2({
                        x: c[0],
                        y: c[1]
                    }, {
                        x: c[2],
                        y: c[3]
                    }, {
                        x: c[4],
                        y: c[5]
                    }, {
                        x: c[6],
                        y: c[7]
                    });

                    q2Array[0][2].onCurve = true;
                    path.push(q2Array[0][1]);
                    path.push(q2Array[0][2]);
                    if (q2Array[1]) {
                        q2Array[1][2].onCurve = true;
                        path.push(q2Array[1][1]);
                        path.push(q2Array[1][2]);
                    }
                });
            }

            return path;
        }

