function parseObject(object) {
  const children = Object.keys(object).map(key => ({
    keyTemplate: parseString(key),
    valueTemplate: parse(object[key])
  }));
  const templateParameters = children.reduce(
    (parameters, child) =>
      parameters.concat(child.valueTemplate.parameters, child.keyTemplate.parameters),
    []
  );
  const templateFn = context => {
    return children.reduce((newObject, child) => {
      newObject[child.keyTemplate(context)] = child.valueTemplate(context);
      return newObject;
    }, {});
  };

  return Template(templateFn, templateParameters);
}

function loadFile(filepath, options, files) {
  if (!files.get(filepath)) files.set(filepath, {});
  const obj = files.get(filepath);
  const filename = (obj.path = filepath);
  const stats = fs.statSync(filename);
  let buffer = fs.readFileSync(filename);

  obj.cacheControl = options.cacheControl;
  obj.maxAge = obj.maxAge ? obj.maxAge : options.maxAge || 0;
  obj.type = obj.mime = mime.lookup(filepath) || 'application/octet-stream';
  obj.mtime = stats.mtime;
  obj.length = stats.size;
  obj.md5 = crypto
    .createHash('md5')
    .update(buffer)
    .digest('base64');

  if (options.buffer) obj.buffer = buffer;

  buffer = null;
  return obj;
}

function _getNetworkConfig(loadConfig, client) {
	let network_config = null;
	let network_data = null;
	let network_config_loc = null;
	if (typeof loadConfig === 'string') {
		network_config_loc = path.resolve(loadConfig);
		logger.debug('%s - looking at absolute path of ==>%s<==', '_getNetworkConfig', network_config_loc);
		const file_data = fs.readFileSync(network_config_loc);
		const file_ext = path.extname(network_config_loc);
		// maybe the file is yaml else has to be JSON
		if ((/(yml|yaml)$/i).test(file_ext)) {
			network_data = yaml.safeLoad(file_data);
		} else {
			network_data = JSON.parse(file_data);
		}
	} else {
		network_data = loadConfig;
	}

	try {
		if (!network_data) {
			throw new Error('missing configuration data');
		}
		if (!network_data.version) {
			throw new Error('"version" is missing');
		}
		const parsing = Client.getConfigSetting('network-config-schema');
		if (!parsing) {
			throw new Error('missing "network-config-schema" configuration setting');
		}
		const pieces = network_data.version.toString().split('.');
		const version = pieces[0] + '.' + pieces[1];
		if (!parsing[version]) {
			throw new Error('common connection profile has an unknown "version"');
		}
		const NetworkConfig = require(parsing[version]);
		network_config = new NetworkConfig(network_data, client, network_config_loc);
	} catch (error) {
		throw new Error(util.format('Invalid common connection profile due to %s', error.message));
	}

	return network_config;
}

function LacesArray(array, options) {

    if (array instanceof Array) {
        options = options || {};
    } else {
        options = array;
        array = [];
    }
    for (var method in LacesArray.prototype) {
        Object.defineProperty(array, method, {
            "value": LacesArray.prototype[method],
            "writable": false
        });
    }
    LacesObject.call(array, options);
    for (var i = 0, length = array.length; i < length; i++) {
        var value = this.wrap(array[i]);
        if (options.bindChildren !== false) {
            this._bindValue(i, value);
        }
        array[i] = value;
    }
    return array;
}

