function(buf) {
		if (!buf || (buf.length == 0)) {
			return null;
		}
		var str;
		try {
			str = buf.toString('base64');
			var lines = [
				"-----BEGIN PUBLIC KEY-----"
			];
			var i = 0;
			while (i < str.length) {
				var chunk = str.substr(i, 64);
				i += chunk.length;
				lines.push(chunk);
			}
			lines.push("-----END PUBLIC KEY-----");
			return lines.join("\n");
		}
		catch(ex) {
			logger.error("error converting DER to PEM, was: " + str);
		}
		return null;
	}

