      // console.log('gm compare results:', err, isEqual, equality, raw);
      if (err) { throw err; }
      isEqual ? deferred.resolve(equality) : deferred.reject([path2, ' is not equal to ', path1, ' (tolerance:', compareOptions.tolerance, ', result:', equality, ')'].join(''));
    });
