function toServer (router) {
  assert.equal(typeof router, 'function')

  const syms = getOwnSymbols(router)
  const sym = syms.length ? syms[0] : router._sym
  assert.ok(sym, 'router should be an instance of wayfarer')

  emit._subrouters = router._subrouters
  emit._routes = router._routes
  emit[sym] = true
  emit.emit = emit
  emit.on = on

  return emit

  // match a route and execute the corresponding callback
  // (obj, obj) -> null
  // original: {path, params parentDefault}
  function emit (route, req, res) {
    assert.equal(typeof route, 'string')
    assert.ok(req, 'no req specified')

    if (!req._ssa) {
      assert.ok(res, 'no res specified')
    }

    // handle server init
    if (isReq(req) && isRes(res)) {
      const ssa = createSsa({}, req, res)
      const dft = { node: { cb: [ router._default ] } }
      return router(route, ssa, dft)
    }

    // handle subrouter
    const params = req
    const parentDefault = res
    router(route, params, parentDefault)
  }

  // register a new route on a method
  // (str, obj) -> obj
  function on (route, methods) {
    assert.equal(typeof route, 'string')
    methods = methods || {}

    // mount subrouter
    if (methods[sym]) return router.on(route, methods)

    assert.equal(typeof methods, 'object')

    // mount http methods
    router.on(route, function (args) {
      demuxSsa(args, function (req, res, params) {
        const meth = methodist(req, defaultFn, methods)
        meth(req, res, params)

        // default function to call if methods don't match
        // null -> null
        function defaultFn () {
          router._default(args)
        }
      })
    })
    return emit
  }
}

function maybeAddChecksumNode(path, nodeType, callback) {
    fsUtils.isPathUnsynced(fs, path, function(err, unsynced) {
      if(err) {
        return callback(err);
      }

      if(unsynced) {
        return callback();
      }

      getChecksum(fs, path, function(err, checksum) {
        if(err) {
          return callback(err);
        }
        // If we shouldn't add the checksum stamp or
        // the node does not exist (cannot add a stamp)
        // immediately add the checksum
        if(!stampNode || checksum === "") {
          return addChecksumNode(path, nodeType, checksum, callback);
        }

        // Stamp the node with the checksum
        fsUtils.setChecksum(fs, path, checksum, function(err) {
          if(err) {
            return callback(err);
          }

          addChecksumNode(path, nodeType, checksum, callback);
        });
      });
    });
  }

function renderDom (vdom, props, isSvg) {
  // render and collect vdom's children
  var collector = new Collector()
  var domChildren = []

  if (vdom.type === 'svg') isSvg = true

  for (var i = 0; i < props.children.length; i++) {
    var result = rawRender(props.children[i], isSvg)
    if (result.nodes) {
      domChildren = domChildren.concat(result.nodes)
      collector.append({ components: result.components, refs: result.refs })
    }
  }

  // create dom element
  var el = isSvg ? document.createElementNS('http://www.w3.org/2000/svg', vdom.type) : document.createElement(vdom.type)
  for (var k in vdom.props) setDomAttrib(el, k, vdom.props[k], isSvg)
  for (i = 0; i < domChildren.length; i++) el.appendChild(domChildren[i])

  if (props.ref) collector.append({ refs: { ref: el, fn: props.ref } })
  collector.append({ nodes: el })
  return collector.get()
}

