function ModalNavigationHandler(element, loop) {
    // ---------------------------------------------- input arguments processing

    if (loop == null) {
        loop = false;
    }
    loop = !!loop;

    // -------------------------------------------------------------- processing

    // -------------------------------------------------------------------------

    var oncatch = function(arg) {
        var navigationInformation = arg.navigationInformation;
        var direction = navigationInformation.direction;
        var origin = navigationInformation.origin;

        var reverse = (direction === 'forward' && origin === 'popup') || (direction === 'backward' && origin === 'browser');
        if (loop) {
            reverse = !reverse;
        }
        ariaTemplatesNavigationManager.focusFirst(element, reverse);
    };

    // -------------------------------------------------------------------------

    var elementInterceptor = ModalNavigationInterceptor({
        getReferenceElement: function() {return element;}
    });

    var viewportInterceptor = ViewportNavigationInterceptor();

    // ------------------------------------------------------------------ return

    return CompositeInterceptor([
        elementInterceptor,
        viewportInterceptor
    ], {
        oncatch: oncatch
    });
}

function checkIfTasksRunning(vCon, tasks, handleError, env) {
    var tasksRunning = tasks.filter(function (t) {
      return (t.status === STATUS.RUNNING || t.status === STATUS.READY);
    });
    if (!tasksRunning.length) {
      var remainingTasks = tasks.filter(function (t) { return (!t.status); });
      var remainingTNames = remainingTasks.map(function (t) { return t.name; });
      var errMsg = sprintf(NO_TASKS_RUNNING_WONT_COMPLETE, remainingTNames.join(', '));
      var emptyTask = { env: env };
      handleError(emptyTask, new Error(errMsg));
    }
  }

