function createDebugFileRouter(adapterPool) {
    var router = express.Router();

    router.get('/:connectionId/:referenceId/*', function(req, res) {
        if (!adapterPool.has(req.params.connectionId)) {
            res.sendStatus(404);
            return;
        }
        var adapter = adapterPool.get(req.params.connectionId);
        adapter.sendRequest('source', { sourceReference: parseInt(req.params.referenceId, 10) }, TIMEOUT, function(response) {
            if (!response.success) {
                res.sendStatus(404);
                return;
            } else {
                if (response.body.mimeType) {
                    res.setHeader('Content-Type', response.body.mimeType);
                }
                res.write(response.body.content);
                res.end();
            }
        });
    });

    return router;
}

function directorySize(path, cb, size) {
  if (size === undefined) {
    size = 0;
  }

  fs.stat(path, function(err, stat) {
    if (err) {
      cb(err);
      return;
    }

    size += stat.size;

    if (!stat.isDirectory()) {
      cb(null, size);
      return;
    }

    fs.readdir(path, function(err, paths) {
      if (err) {
        cb(err);
        return;
      }

      async.map(paths.map(function(p) { return path + '/' + p }), directorySize, function(err, sizes) {
        size += sizes.reduce(function(a, b) { return a + b }, 0);
        cb(err, size);
      })
    })
  })
}

function DunFile(startCoord, rawPillarData, dunName) {
    this.startCol = startCoord[0];
