function mockServer(app) {
        const jsonRouter = jsonServer.router(db);

        const shouldMockReq = req => {
          return (
            req.method !== "GET" ||
            (req.headers.accept &&
              req.headers.accept.indexOf("application/json") !== -1)
          );
        };

        if (serverOpts.delay) {
          app.use((req, res, next) => {
            if (shouldMockReq(req)) {
              return pause(serverOpts.delay)(req, res, next);
            }
            return next();
          });
        }

        app.use(jsonServer.rewriter(rewrites));

        // user defined routers
        app.use(jsonServer.bodyParser);

        // user query normalizr
        app.use((req, res, next) => {
          if (shouldMockReq(req)) {
            req.query = toJsonServer(req.query);
            return next();
          }
          return next();
        });

        routers.forEach(router => app.use(router));

        // json server router
        app.use((req, res, next) => {
          if (shouldMockReq(req)) {
            return jsonRouter(req, res, next);
          }
          return next();
        });

        return app;
      }

function showRipple(e) {
    if (!TouchHandler.isAllow(e)) {
      return;
    }

    TouchHandler.register(e);

    // Chrome 59 点击滚动条时，会在 document 上触发事件
    if (e.target === document) {
      return;
    }

    var $ripple;
    var $target = $(e.target);

    // 获取含 .mdui-ripple 类的元素
    if ($target.hasClass('mdui-ripple')) {
      $ripple = $target;
    } else {
      $ripple = $target.parents('.mdui-ripple').eq(0);
    }

    if ($ripple.length) {

      // 禁用状态的元素上不产生涟漪效果
      if ($ripple[0].disabled || $ripple.attr('disabled') !== null) {
        return;
      }

      if (e.type === 'touchstart') {
        var hidden = false;

        // toucstart 触发指定时间后开始涟漪动画
        var timer = setTimeout(function () {
          timer = null;
          Ripple.show(e, $ripple);
        }, Ripple.delay);

        var hideRipple = function (hideEvent) {
          // 如果手指没有移动，且涟漪动画还没有开始，则开始涟漪动画
          if (timer) {
            clearTimeout(timer);
            timer = null;
            Ripple.show(e, $ripple);
          }

          if (!hidden) {
            hidden = true;
            Ripple.hide(hideEvent, $ripple);
          }
        };

        // 手指移动后，移除涟漪动画
        var touchMove = function (moveEvent) {
          if (timer) {
            clearTimeout(timer);
            timer = null;
          }

          hideRipple(moveEvent);
        };

        $ripple
          .on('touchmove', touchMove)
          .on('touchend touchcancel', hideRipple);

      } else {
        Ripple.show(e, $ripple);
        $ripple.on('touchmove touchend touchcancel mousemove mouseup mouseleave', Ripple.hide);
      }
    }
  }

