                hash = hash.trim();
                var page;
                if (hash.substr(0, hashPrefix.length + 2) == '/' + hashPrefix + '/') {
                    page = hash.substr(hashPrefix.length + 2).trim().split( '/' )[0];
                    that.show(page);
                }
            });
        });
    }
}

