        // one so just return original app name.
        if (counter > 255) {
          return appName;
        // Recurse with an incremented counter.
        } else if (!counter) {
          return rec(1);
        // Recurse with an incremented counter.
        } else {
          return rec(counter + 1);
        }
      // App name does NOT already exist, we found it!
      } else {
        return name;
      }
    });
  }

function sortObject(object) {
    var keys = Object.keys(object);
    var sorted = {};

    var options = {
      sensitivity: 'base'
    };

    function compare(a, b) {
      return a.localeCompare(b, options);
    }

    keys.sort(compare);

    for (var index in keys) {
      if (keys[index]) {
        var key = keys[index];

        if (Array.isArray(object[key])) {
          sorted[key] = object[key].sort(compare);
        } else if (typeof object[key] === 'object') {
          sorted[key] = sortObject(object[key]);
        } else {
          sorted[key] = object[key];
        }
      }
    }

    return sorted;
  }

