protected function prependRepositories(RootPackageInterface $root)
    {
        if (!isset($this->json['repositories'])) {
            return;
        }
        $repoManager = $this->composer->getRepositoryManager();
        $newRepos = array();

        foreach ($this->json['repositories'] as $repoJson) {
            if (!isset($repoJson['type'])) {
                continue;
            }
            $this->logger->info("Prepending {$repoJson['type']} repository");
            $repo = $repoManager->createRepository(
                $repoJson['type'],
                $repoJson
            );
            $repoManager->prependRepository($repo);
            $newRepos[] = $repo;
        }

        $unwrapped = self::unwrapIfNeeded($root, 'setRepositories');
        $unwrapped->setRepositories(array_merge(
            $newRepos,
            $root->getRepositories()
        ));
    }

public function get($key, array $invalidationTags = null)
    {
        if (!empty($invalidationTags)) {
            return $this->getTaggedCache($key, $invalidationTags);
        }

        $serialized = $this->engine->get($key);
        if (empty($serialized)) {
            return null;
        }

        $cache = @unserialize($serialized);
        $value = isset($cache[0]) ? $cache[0] : null;

        return $value;
    }

