        $key = $this->key;
        //多次加密
        for ($i = 0; $i < $this->times; $i++) {
            //密钥变换
            $key[16] = &$key[0]; //第17，18个字节用作计算第16个字节
            $key[17] = &$key[1];
            for ($j = 0; $j < 16; $j++) {
                $key[$j] = (($key[$j] + $b[$j]) % 256 & $key[$j + 2]) | ($key[$j + 1] & (~$key[$j + 2])); // 非线性变换，运算公式( i & i+2 ) | ( i+1 & (~(i+2)) )
            }
            $key = md5(implode('', $key), true);
            $key = $this->convert($key);
            //加密
            for ($j = 0, $k = 0; $j < $n; $j++) {
                $tmp = ord($data[$j]);
                $tmp ^= $key[$k]; //每个字符对本轮密钥依次异或
                $k        = (++$k % 16); //确保k在0-15
                $data[$j] = chr($tmp); //单字节整数转ascci
            }
        }
        return $data;
    }

protected function resolveServiceArgument(string $name, ReflectionClass $type, ReflectionParameter $param)
    {
        $type_class = $type->getName();

        if ($type_class === $name) {
            throw new RuntimeException('class '.$type_class.' can not depend on itself');
        }

        try {
            return $this->traverseTree($name, $type_class);
        } catch (\Exception $e) {
            if ($param->isDefaultValueAvailable() && null === $param->getDefaultValue()) {
                return null;
            }

            throw $e;
        }
    }

