public function render($default)
	{
		$attr = $this->html;
		$attr .= $this->class_name ? ' class="' . $this->class_name . '"' : '';

		if ($this->value == $default)
		{
			$attr .= ' selected="selected"';
		}

		return sprintf($this->option, $this->value, $this->name, $attr) . PHP_EOL;
