public function parseAll($message)
    {
        $tail = $message;
        $messages = array();
        do {
            $parsed = $this->parse($tail);
            if ($parsed === null) {
                break;
            }
            $messages[] = $parsed;
            $tail = empty($parsed['tail']) ? null : $parsed['tail'];
        } while ($tail !== null);
        return $messages;
    }

