private function getDirective()
    {
        switch (strtolower($this->type)) {
            case 'digest':
                return 'Digest ' . $this->buildDirectiveParameters(array(
                    'realm' => $this->realm,
                    'qop' => 'auth',
                    'nonce' => uniqid(),
                    'opaque' => md5($this->realm),
                ));

            default:
                return 'Basic ' . $this->buildDirectiveParameters(array(
                    'realm' => $this->realm
                ));
        }
    }

public function applyFilterDateRange(Filter\FilterDateRange $filter)
	{
		$conditions = $filter->getCondition();

		$value_from = $conditions[$filter->getColumn()]['from'];
		$value_to = $conditions[$filter->getColumn()]['to'];

		if ($value_from) {
			$this->data_source->where('CONVERT(varchar(10), %n, 112) >= ?', $filter->getColumn(), $value_from);
		}

		if ($value_to) {
			$this->data_source->where('CONVERT(varchar(10), %n, 112) <= ?', $filter->getColumn(), $value_to);
		}
	}

