public function renderCommandList ()
    {
        echo PHP_EOL.pack('c',0x1B).'[1m-- EmeraldBeans CommandsList --'.pack('c',0x1B).'[0m'.PHP_EOL;

        $command_dir = LIB.'/'.APP.'/Commands';
        $read_paths = array($command_dir, dirname(__FILE__).'/Command/Provision');

        foreach ($read_paths as $read_path) {
            if ($dh = @opendir($read_path)) {
                while ($command = readdir($dh)) {
                    // コマンドクラスを取得していく
                    if (! is_dir($read_path.'/'.$command) && preg_match('/\.php/', $command)) {
                        require_once $read_path.'/'.$command;

                        $limit = 30;
                        $class = str_replace('.php', '', $command);
                        $class_str = mb_strlen($class);

                        $help = $class::help();
                        $help = explode(PHP_EOL, $help);
                        $text = '';

                        foreach ($help as $row => $help_message) {
                            $space = '';
                            $class_name = ' ';

                            if ($row == 0) {
                                // 一行目はクラス名を記載する
                                $space_limit = $limit - $class_str;
                                $class_name  = '  '.pack('c',0x1B).'[1;33m'.$class.':';
                            } else {
                                $space_limit = $limit;
                            }

                            for ($i = 0; $i < $space_limit; $i++) {
                                $space .= ' ';
                            }

                            echo $class_name.$space.pack('c',0x1B).'[0m'.$help_message.PHP_EOL;
                        }
                    }
                }
                closedir($dh);
            }
        }

        echo PHP_EOL;
    }

static public function getItemsForCatalog($nb_catalog, int $level)
    {
        $nb_catalog_id = nb_getMixedValue($nb_catalog, NABU_CATALOG_FIELD_ID);
        if (is_numeric($nb_catalog_id)) {
            $retval = CNabuCatalogItem::buildObjectListFromSQL(
                NABU_CATALOG_ITEM_FIELD_ID,
                'SELECT *
                   FROM nb_catalog_item
                  WHERE nb_catalog_id=%catalog_id$d '
                . ($level > 0 ? 'AND nb_catalog_item_level<=%level$d ' : '')
                . 'ORDER BY nb_catalog_item_order ASC',
                array(
                    'catalog_id' => $nb_catalog_id,
                    'level' => $level
                ),
                ($nb_catalog instanceof CNabuCatalog ? $nb_catalog : null)
            );
            if ($nb_catalog instanceof CNabuCatalog) {
                $retval->setCatalog($nb_catalog);
            }
        } else {
            if ($nb_catalog instanceof CNabuCatalog) {
                $retval = new CNabuCatalogItemList($nb_catalog);
                $retval->setOwner($nb_catalog);
            } else  {
                $retval = new CNabuCatalogItemList();
            }
        }

        return $retval;
    }

