public function configure(Object $object): ConfigurationInterface
    {
        foreach ($this as $key => $value) {
            $method = 'set' . ucfirst($key);
            $property = lcfirst($key);
            $reflection = new \ReflectionClass($object);

            if ($reflection->hasMethod($method)) {
                $reflectionMethod = $reflection->getMethod($method);
                $reflectionMethod->setAccessible(true);
                $reflectionMethod->invoke($object, $value);
                continue;
            }

            if ($reflection->hasProperty($property) || isset($object->$property)) {
                $reflectionProperty = $reflection->getProperty($property);
                $reflectionProperty->setAccessible(true);
                $reflectionProperty->setValue($object, $value);
            }
        }

        return $this;
    }

public function loadFile($path) {
        $config = null;

        try {
            $config = require $path;
        } catch (Exception $ex) {}

        if ( ! is_array($config)) {
            throw new InvalidConfigFormatException(
                s('ArrayConfigDriver expects config at path %s to be of format array[key => value].', $path)
            );
        }

        return $config;
    }

private function isAutoWirable($id): bool
    {
        if (is_string($id) && class_exists($id)) {

            if (count($this->interfaces) > 0) {

                return (bool) array_intersect($this->interfaces, class_implements($id));

            }

            return true;

        }

        return false;
    }

public function getTasks()
    {
        if (!array_key_exists('environments', $this->configuration) || !is_array($this->configuration['environments'])) {
            return [];
        }

        if (!array_key_exists($this->environment, $this->configuration['environments'])) {
            return [];
        }

        if (array_key_exists($this->stage, $this->configuration['environments'][$this->environment])) {
            if (is_array($this->configuration['environments'][$this->environment][$this->stage])) {
                return $this->configuration['environments'][$this->environment][$this->stage];
            }
        }

        return [];
    }

