public function writeDrushAlias()
    {
        $drush_alias_file_path = "{$_SERVER['HOME']}/.drush/terra.{$this->app->name}.aliases.drushrc.php";

        $drush_alias_file = array();
        $drush_alias_file[] = '<?php';

        foreach ($this->app->environments as $environment_name => $environment) {
            $factory = new self($environment, $this->app);
            $path = "/app/" . $environment['document_root'];
            $drush_alias_file[] = '// DO NOT EDIT. This is generated by Terra. Any changes will be overridden when the environment is re-enabled.';
            $drush_alias_file[] = "\$aliases['{$environment_name}'] = array(";
            $drush_alias_file[] = "  'uri' => '{$factory->getHost()}:{$factory->getPort()}',";
            $drush_alias_file[] = "  'root' => '$path',";
            $drush_alias_file[] = "  'remote-host' => '{$factory->getHost()}',";
            $drush_alias_file[] = "  'remote-user' => 'terra',";
            $drush_alias_file[] = "  'ssh-options' => '-p {$factory->getDrushPort()}',";
            $drush_alias_file[] = ');';
        }

        $fs = new FileSystem();

        try {
            $fs->dumpFile($drush_alias_file_path, implode("\n", $drush_alias_file));

            return true;
        } catch (IOException $e) {
            return false;
        }
    }

public function execute($trackId = null)
    {
        $batch = $this->getBatch();
        $select = $this->db->select();

        // Join conditions on rounds, handle and / or conditions when implemented
        $select->from('gems__conditions', array(
            'gcon_id', 'gcon_type', 'gcon_class', 'gcon_name', 'gcon_condition_text1', 'gcon_condition_text2', 'gcon_condition_text3', 'gcon_condition_text4',
            ))  ->joinInner('gems__rounds', 'gems__conditions.gcon_id = gems__rounds.gro_condition', array())
                ->where('gems__rounds.gro_id_track = ?', $trackId)
                ->distinct(true);
        // \MUtil_Echo::track($select->__toString(), $roundId);

        $data = $this->db->fetchAll($select);
        // \MUtil_Echo::track($data);

        if ($data) {
            $this->exportTypeHeader('conditions');
            $this->exportFieldHeaders(reset($data));

            foreach($data as $row)
            {
                $this->exportFieldData($row);
                $count = $batch->addToCounter('conditions_exported');
            }
            $this->exportFlush();

            $batch->setMessage('conditions_export', sprintf(
                    $this->plural('%d condition exported', '%d conditions exported', $count),
                    $count
                    ));
        }
    }

