public function getItems(Query $query)
    {
        if ($query->hasSortField()) {
            $this->search->addSort($query->getSortField(), $query->getSortOrder());
        }

        $inputDefinition = $query->getInputDefinition();

        $response = $this
            ->search
            ->setPageParameter($inputDefinition->getPagerParameter())
            ->setFulltextParameterName($inputDefinition->getSearchParameter())
            ->addField('_id')
            ->setLimit($query->getLimit())
            ->doSearch($query->getRouteParameters()) // FIXME this should be the sanitized filters + a few others (sort, etc...)
        ;

        $nodeList = $this->entityManager->getStorage('node')->loadMultiple($response->getAllNodeIdentifiers());
        $this->preloadDependencies($nodeList);

        return $this->createResult($nodeList, $response->getTotal());
    }

private function getRedisServers(array $servers)
    {
        if (!empty($servers)) {
            foreach ($servers as $server) {
                if (isset($server['socket'])) {
                    $server = [
                        'server' => array_get($server, 'socket', ''),
                        'ttl' => array_get($server, 'ttl', null),
                    ];
                } else {
                    $host = array_get($server, 'host', '');
                    // Check for both server/host - fallback due to cache using server
                    $host = !empty($host) ?: array_get($server, 'server', '127.0.0.1');
                    $server = [
                        'server' => $host,
                        'port' => array_get($server, 'port', 11211),
                        'ttl' => array_get($server, 'ttl', null),
                    ];
                }
                yield $server;
            }
        } else {
            yield ['server' => '127.0.0.1', 'port' => '6379', 'ttl' => 0.5];
        }
    }

protected function withFreshQueryLog( $callback ) {
		$loggingQueries = $this->loggingQueries;

		// First we will back up the value of the logging queries property and then
		// we'll be ready to run callbacks. This query log will also get cleared
		// so we will have a new log of all the queries that are executed now.
		$this->enableQueryLog();

		$this->getLogger()->flushQueryLog();

		// Now we'll execute this callback and capture the result. Once it has been
		// executed we will restore the value of query logging and give back the
		// value of the callback so the original callers can have the results.
		$result = $callback();

		$this->loggingQueries = $loggingQueries;

		return $result;
	}

private function httpBuildQuery($params)
    {
        $query = [];
        foreach ($params as $key => $param) {
            if (!is_array($param)) {
                continue;
            }
            // when a param has many values, it generate the query string separated to join late
            foreach ($param as $subParam) {
                $query[] = http_build_query([$key => $subParam]);
            }
            unset($params[$key]);
        }

        // join queries strings
        $query[] = http_build_query($params);
        $query = implode('&', $query);

        return $query;
    }

public function read($length)
    {
        if (!$this->handle) $this->open('r');
        return $this->fs->fread($this->handle, $length);
