static function arrayExtract(array $keys, array $array, array $callbacks = []) {
    // Set extracted
    $extracted = [];
    // Loop through keys
    foreach ($keys as $key) {
      // Add to extracted, only if it exists
      if (array_key_exists($key, $array)) {
        // Set item
        $item = $array[$key];
        // If there's a callback
        if (isset($callbacks[$key]) && is_callable($callbacks[$key])) {
          // Call it
          $item = call_user_func_array($callbacks[$key], [$item]);
        }
        // Add to extracted
        $extracted[$key] = $item;
      }
    }
    // Return extracted
    return $extracted;
  }

protected function foreignKeyStringFromArray($dataMember, $opening, $sep = ', ')
    {
        if (empty($this->$dataMember)) {
            return 0;
        }
        //$query = '';
        $count = count($this->$dataMember);
        for($i=0; $i<$count; $i++) {
            $item = $this->{$dataMember}[$i];

            $this->query .= ', CONSTRAINT '.'fk_'.$item[0].' FOREIGN KEY ('.$item[0].') REFERENCES '.$item[1].' ('.$item[2].')';
            if ($count-1 != $i) {
                $this->query .= $sep;
            }
        }
    }

public function createConsumer(Destination $destination): Consumer
    {
        $destination instanceof Topic
            ? InvalidDestinationException::assertDestinationInstanceOf($destination, InteropAmqpTopic::class)
            : InvalidDestinationException::assertDestinationInstanceOf($destination, InteropAmqpQueue::class)
        ;

        if ($destination instanceof AmqpTopic) {
            $queue = $this->createTemporaryQueue();
            $this->bind(new AmqpBind($destination, $queue, $queue->getQueueName()));

            return new AmqpConsumer($this, $queue);
        }

        return new AmqpConsumer($this, $destination);
    }

private function filterByPhpVersion(array $versions)
    {
        $versionInfo = $this->getAvailableVersions();

        return array_filter($versions, function ($version) use ($versionInfo) {
            if (isset($versionInfo[$version]['php']['min'])
                && version_compare(PHP_VERSION, $versionInfo[$version]['php']['min'], '<')) {
                return false;
            } elseif (isset($versionInfo[$version]['php']['max'])
                && version_compare(PHP_VERSION, $versionInfo[$version]['php']['max'], '>')) {
                return false;
            }

            return true;
        });
    }

public function truncate(int $maximum) : Collection
    {
        return $this->pipe(
            function (array $value) use ($maximum) : array {
                return count($value) > $maximum
                    ? array_slice($value, 0, $maximum)
                    : $value;
            }
        );
    }

