public function onSchemaIndexDefinition(SchemaIndexDefinitionEventArgs $event): void
    {
        // Skip for doctrine/dbal >= 2.9
        if (method_exists(AbstractPlatform::class, 'supportsColumnLengthIndexes')) {
            return;
        }

        $connection = $event->getConnection();

        if (!$connection->getDatabasePlatform() instanceof MySqlPlatform) {
            return;
        }

        $data = $event->getTableIndex();

        // Ignore primary keys
        if ('PRIMARY' === $data['name']) {
            return;
        }

        $columns = [];
        $query = sprintf("SHOW INDEX FROM %s WHERE Key_name='%s'", $event->getTable(), $data['name']);
        $result = $connection->executeQuery($query);

        while ($row = $result->fetch()) {
            if (null !== $row['Sub_part']) {
                $columns[] = sprintf('%s(%s)', $row['Column_name'], $row['Sub_part']);
            } else {
                $columns[] = $row['Column_name'];
            }
        }

        $event->setIndex(
            new Index(
                $data['name'],
                $columns,
                $data['unique'],
                $data['primary'],
                $data['flags'],
                $data['options']
            )
        );

        $event->preventDefault();
    }

protected function setDrupalVmStatus() {
    $result = $this->executor->execute("vagrant status --machine-readable")
      ->interactive(FALSE)
      ->printMetadata(TRUE)
      ->setVerbosityThreshold(VerbosityThresholdInterface::VERBOSITY_VERY_VERBOSE)
      ->run();
    $output = $result->getMessage();
    if (!$result->wasSuccessful() || !$output) {
      $this->drupalVmStatus = [];
      return FALSE;
    }
    $lines = explode("\n", $output);
    foreach ($lines as $line) {
      $parsed_line = explode(',', $line);
      if (count($parsed_line) < 4) {
        continue;
      }
      list($timestamp, $target, $type, $data) = $parsed_line;
      $this->drupalVmStatus[$target][$type] = $data;
      $this->logger->debug("vagrant $target.$type = $data");
    }
  }

protected function busqueda($base, $filtro, $atributos, $limite = 499, $ordenar = false){
        try {
            if (!($busquedaLdap = ldap_search($this->conexionLdap, $base, $filtro, $atributos, 0, $limite))){
                throw new ErrorException (ldap_error($this->conexionLdap));
            }
            if ($ordenar) {
                ldap_sort($this->conexionLdap, $busquedaLdap, $filtro[0]);
            }
            // La función muere en el momento que un throw es invocado. Así las cosas
            // TODO: Básicamente, debo quitar esto lo más pronto posible.
            // Esta operación a estas alturas no representa un error, pero si debe cortar muchas cosas
            if (!($datos = $this->iterarEntradas($busquedaLdap, $atributos))) {
                throw new ErrorException ('La busqueda no devuelve entradas');
            }             
            return $datos;
            // Hacemos la verdadera iteracion
        } catch (ErrorException $e) {
            $this->configurarErrorLdap('Error en búsqueda', $e->getMessage());
            return FALSE;
        }
    }

protected function &getValueFromObjectTree(array $objectPathArray, &$objectTree = null)
    {
        if (is_null($objectTree)) {
            $objectTree = &$this->objectTree;
        }

        if (count($objectPathArray) > 0) {
            $currentKey = array_shift($objectPathArray);
            if (is_numeric($currentKey)) {
                $currentKey = (int)$currentKey;
            }
            if (!isset($objectTree[$currentKey])) {
                $objectTree[$currentKey] = [];
            }
            $value = &$this->getValueFromObjectTree($objectPathArray, $objectTree[$currentKey]);
        } else {
            $value = &$objectTree;
        }
        return $value;
    }

