public function generate($byteCount)
    {
        $bytes = '';

        if (self::isSupported()) {
            $sslStrong = false;
            $sslBytes = openssl_random_pseudo_bytes($byteCount, $sslStrong);
            if ($sslStrong) {
                $bytes = $sslBytes;
            }
            unset ($sslStrong);
        }

        return str_pad($bytes, $byteCount, chr(0));
    }

