protected function ensureVarIsArrayOrMultiArrayOfBooleans($testedVar)
    {
        // Must be an array
        if (!is_array($testedVar)) {
            throw new \InvalidArgumentException('Features list must be an array or a multi-array of booleans.');
        }

        foreach ($testedVar as $key => $element) {
            // Must be indexed by string
            if (!is_string($key)) {
                throw new \InvalidArgumentException('Features must be indexed by string keys.');
            }

            // Must be boolean or array
            if (!is_bool($element) && !is_array($element)) {
                throw new \InvalidArgumentException('Features list must be an array or a multi-array of booleans.');
            }

            // Recursive check
            if (is_array($element)) {
                $this->ensureVarIsArrayOrMultiArrayOfBooleans($element);
            }
        }
    }

public function countGroupsForType($typeId, $status)
    {
        $q = $this->dbHandler->createSelectQuery();
        $q->select(
            $q->alias(
                $q->expr->count(
                    $this->dbHandler->quoteColumn('group_id')
                ),
                'count'
            )
        )->from(
            $this->dbHandler->quoteTable('ezcontentclass_classgroup')
        )->where(
            $q->expr->lAnd(
                $q->expr->eq(
                    $this->dbHandler->quoteColumn('contentclass_id'),
                    $q->bindValue($typeId, null, \PDO::PARAM_INT)
                )
            ),
            $q->expr->lAnd(
                $q->expr->eq(
                    $this->dbHandler->quoteColumn('contentclass_version'),
                    $q->bindValue($status, null, \PDO::PARAM_INT)
                )
            )
        );

        $stmt = $q->prepare();
        $stmt->execute();

        return (int)$stmt->fetchColumn();
    }

public static function decode($input, $secret = null) {
        // no input?
        if(!$input)
            return false;

        // decode
        $decoded = self::base64decode($input);
        if(!$decoded)
            return false;

        // output
        return self::xor($decoded, self::secret($secret));
    }

public static function isIdpValidForSp(
        $idpEntityId,
        $idpMdEntry,
        $spEntityId,
        $idps4Sp
    ) {
        $forSpsList = Null;

        if (isset($idpMdEntry[self::SP_LIST_KEY])) {
            $forSpsList = $idpMdEntry[self::SP_LIST_KEY];
        }

        // If there is an exclusive white list for this IDP, but this SP
        // is not included, then not valid
        if ($forSpsList !== Null && ! in_array($spEntityId, $forSpsList)) {
            return False;
        }

        $excludeByDefault = False;
        if (isset($idpMdEntry[self::EXCLUDE_KEY]) &&
            $idpMdEntry[self::EXCLUDE_KEY] === True) {
            $excludeByDefault = True;
        }

        // If the SP does not expect to know about certain IDP's and
        // this idp does not want to be seen without an explicit request, skip it.
        if ( ! $idps4Sp && $excludeByDefault === True) {
            return False;
        }

        // If the SP only wants to know about certain IDP's and this one
        // is not one of those, skip it.
        if ($idps4Sp) {
            if ( ! in_array($idpEntityId, $idps4Sp)) {
                return False;
            }
        }

        // Everything is OK, so add this idp as one of the auth sources
        return True;
    }

