public function findOneByEmail($email)
    {
        foreach ($this->users as $user) {
            if ($user->getEmail() === $email) {
                return $user;
            }
        }
        $result = $this->getQueryBuilder()
            ->where('u.email = :email')
            ->setParameter(':email', $email)
            ->execute();
        $row = $result->fetch(\PDO::FETCH_OBJ);

        if (!$row) {
            return null;
        }
        $entity = $this->rowToEntity($row);
        $this->replace($entity);
        return $entity;
    }

protected function addError(IRule $rule)
    {
        if ($rule instanceof ConditionalRule) {
            $rules = $rule->getRules();
        } else {
            $rules = [$rule];
        }

        foreach ($rules as $singleRule) {
            $this->errorSlugsAndPlaceholders[] = [
                'slug' => $singleRule->getSlug(),
                'placeholders' => $singleRule instanceof IRuleWithErrorPlaceholders ? $singleRule->getErrorPlaceholders() : []
            ];
        }
    }

public function hasChild($key = null, $value = null, Collect $data = null)
    {
        if (func_num_args() < 3) {
            $data = $this->data;
            $key = $this->parent;
            $value = current(func_get_args());
        }

        $child = false;

        $data->each(function ($item) use (&$child, $key, $value) {

            if (intval($item[$key]) == intval($value) && !$child) {
                $child = true;
            }

        });

        return $child;
    }

