protected function captureResponseMetadata($response, $key)
    {
        if ($response instanceof \Aws\Exception\AwsException) {
            //TODO: AwsException->getTransferInfo()['http'] only has empty arrays, even with stats enabled?
            $this->addTransferStats(new TransferStats($response->getTransferInfo(), $this->getExecutedCommand($key)), $key);

            return;
        }

        $this->addTransferStats(new TransferStats($response['@metadata']['transferStats'], $this->getExecutedCommand($key)), $key);

        if (isset($response['ConsumedCapacity'])) {
            //make array structure uniform (single table operation vs. multi)
            $capacityMetadatas = isset($response['ConsumedCapacity']['TableName']) ?
                [$response['ConsumedCapacity']] : $response['ConsumedCapacity'];

            foreach ($capacityMetadatas as $capacityMetadata) {
                //if there is existing capacity consumption data for this table it needs to be merged with the new results
                $previousCapacity = isset($this->consumedCapacity[$capacityMetadata['TableName']]) ?
                    $this->consumedCapacity[$capacityMetadata['TableName']] : null;

                $this->consumedCapacity[$capacityMetadata['TableName']] = new ConsumedCapacity(
                    $capacityMetadata,
                    $this->parameters['ReturnConsumedCapacity'],
                    $previousCapacity
                );
            }
        }

        if (!empty($response['ItemCollectionMetrics'])) {
            foreach ($response['ItemCollectionMetrics'] as $tableName => $collections) {
                foreach ($collections as $collection) {
                    $this->itemCollectionMetrics[$tableName][current($collection['ItemCollectionKey'])] = new ItemCollectionMetrics($collection);
                }
            }
        }
    }

