public function formatNumberToHumanReadable($number, $precision = 0, $method = 'common')
    {
        if ($number >= 1000000) {
            // Divide by 1000000 to get 1M, 1.23M, etc.
            $value     = $number / 1000000;
            $extension = 'M';
        } elseif ($number >= 1000 && $number < 1000000) {
            // Divide by 1000, to get 1K, 1.33K, etc.
            $value     = $number / 1000;
            $extension = 'K';
        } else {
            // Less than 1000, just return the number, unformatted, not rounded
            $value     = $number;
            $extension = '';
        }

        if ('common' == $method) {
            $value = round($value, $precision);
        } else {

            if ('ceil' != $method && 'floor' != $method) {
                throw new \RuntimeException('The number_to_human_readable filter only supports the "common", "ceil", and "floor" methods.');
            }

            $value = $method($value * pow(10, $precision)) / pow(10, $precision);
        }

        return $value.$extension;
    }

protected function parseMnemonic($mnemonic)
    {
        $words = explode(' ', $mnemonic);
        if (count($words) %3 !== 0) throw new \InvalidArgumentException('Invalid mnemonic (number of words must be a multiple of 3)');

        $wordBitstrings = [];
        foreach ($words as $word) {
            $wordIdx = $this->getWordIndex($word);

            // Convert $wordIdx to an 11-bit number (preserving 0s)
            $wordBitstrings[] = str_pad(decbin($wordIdx), 11, '0', STR_PAD_LEFT);
        }

        // Return a string representing each bit
        return join('', $wordBitstrings);
    }

