public function diffForHumans(Time $other = null)
        {
            $isNow = $other === null;

            if ($isNow) {
                $other = static::now($this->tz);
            }

            $isFuture = $this->gt($other);

            $delta = $other->diffInSeconds($this);

            // a little weeks per month, 365 days per year... good enough!!
            $divs = array(
                'second' => self::SECONDS_PER_MINUTE,
                'minute' => self::MINUTES_PER_HOUR,
                'hour' => self::HOURS_PER_DAY,
                'day' => self::DAYS_PER_WEEK,
                'week' => 30 / self::DAYS_PER_WEEK,
                'month' => self::MONTHS_PER_YEAR
            );

            $unit = 'year';

            foreach ($divs as $divUnit => $divValue) {
                if ($delta < $divValue) {
                    $unit = $divUnit;
                    break;
                }

                $delta = $delta / $divValue;
            }

            $delta = (int) $delta;

            if ($delta == 0) {
                $delta = 1;
            }

            $txt = $delta . ' ' . $unit;
            $txt .= $delta == 1 ? '' : 's';

            if ($isNow) {
                if ($isFuture) {
                    return $txt . ' from now';
                }

                return $txt . ' ago';
            }

            if ($isFuture) {
                return $txt . ' after';
            }

            return $txt . ' before';
        }

