public function hasLoop(): bool {
        $tortoise = $this->getHead();
        $hare = $this->getHead();

        while ($tortoise !== null && $hare->getNext() !== null) {
            $hare = $hare->getNext()->getNext();

            if (Comparator::equals($tortoise->getValue(), $hare->getValue())) {
                return true;
            }

            $tortoise = $tortoise->getNext();
        }
        return false;
    }

protected function applyImageUpdated(AbstractImageUpdated $imageUpdated)
    {
        $document = $this->loadDocumentFromRepository($imageUpdated);

        $offerLd = $document->getBody();

        if (!isset($offerLd->mediaObject)) {
            throw new \Exception('The image to update could not be found.');
        }

        $updatedMediaObjects = [];

        foreach ($offerLd->mediaObject as $mediaObject) {
            $mediaObjectMatches = (
                strpos(
                    $mediaObject->{'@id'},
                    (string)$imageUpdated->getMediaObjectId()
                ) > 0
            );

            if ($mediaObjectMatches) {
                $mediaObject->description = (string)$imageUpdated->getDescription();
                $mediaObject->copyrightHolder = (string)$imageUpdated->getCopyrightHolder();

                $updatedMediaObjects[] = $mediaObject;
            }
        };

        if (empty($updatedMediaObjects)) {
            throw new \Exception('The image to update could not be found.');
        }

        return $document->withBody($offerLd);
    }

public function delete($resourceOrEvent, $hard = false)
    {
        $event = $resourceOrEvent instanceof ResourceEvent ? $resourceOrEvent : $this->createResourceEvent($resourceOrEvent);
        $event->setHard($event->getHard() || $hard);
        $this->dispatcher->dispatch($this->config->getEventName('pre_delete'), $event);

        if (!$event->isPropagationStopped()) {
            $eventManager = $this->manager->getEventManager();
            $disabledListeners = [];
            if ($event->getHard()) {
                foreach ($eventManager->getListeners() as $eventName => $listeners) {
                    foreach ($listeners as $listener) {
                        if ($listener instanceof SoftDeleteableListener) {
                            $eventManager->removeEventListener($eventName, $listener);
                            $disabledListeners[$eventName] = $listener;
                        }
                    }
                }
            }

            $this->removeResource($event);

            if (!empty($disabledListeners)) {
                foreach($disabledListeners as $eventName => $listener) {
                    $eventManager->addEventListener($eventName, $listener);
                }
            }

            $this->dispatcher->dispatch($this->config->getEventName('post_delete'), $event);
        }

        return $event;
    }

public function hasComponentType($class_name) {
    /** @var \ChapterThree\AppleNewsAPI\Document\Components\Component $comp */
    foreach ($this->components as $comp) {
      if ($comp instanceof $class_name) {
        return TRUE;
      }
      if ($comp instanceof ComponentNested) {
        /** @var \ChapterThree\AppleNewsAPI\Document\Components\ComponentNested $comp */
        if ($comp->hasComponentType($class_name)) {
          return TRUE;
        }
      }
    }
    return FALSE;
  }

