public function writeTo(\Protobuf\WriteContext $context)
    {
        $stream      = $context->getStream();
        $writer      = $context->getWriter();
        $sizeContext = $context->getComputeSizeContext();

        if ($this->OriginalInvoiceDateAndNumber === null) {
            throw new \UnexpectedValueException('Field "\\AgentSIB\\Diadoc\\Api\\Proto\\Events\\EncryptedInvoiceCorrectionMetadata#OriginalInvoiceDateAndNumber" (tag 1) is required but has no value.');
        }

        if ($this->OriginalInvoiceDateAndNumber !== null) {
            $writer->writeVarint($stream, 10);
            $writer->writeVarint($stream, $this->OriginalInvoiceDateAndNumber->serializedSize($sizeContext));
            $this->OriginalInvoiceDateAndNumber->writeTo($context);
        }

        if ($this->OriginalInvoiceRevisionDateAndNumber !== null) {
            $writer->writeVarint($stream, 18);
            $writer->writeVarint($stream, $this->OriginalInvoiceRevisionDateAndNumber->serializedSize($sizeContext));
            $this->OriginalInvoiceRevisionDateAndNumber->writeTo($context);
        }

        if ($this->InvoiceCorrectionRevisionDateAndNumber !== null) {
            $writer->writeVarint($stream, 26);
            $writer->writeVarint($stream, $this->InvoiceCorrectionRevisionDateAndNumber->serializedSize($sizeContext));
            $this->InvoiceCorrectionRevisionDateAndNumber->writeTo($context);
        }

        if ($this->extensions !== null) {
            $this->extensions->writeTo($context);
        }

        return $stream;
    }

