public function isMobile(): bool
    {
        // 如果有HTTP_X_WAP_PROFILE则一定是移动设备
        if (isset($_SERVER['HTTP_X_WAP_PROFILE'])) {
            return true;
        }

        // 如果via信息含有wap则一定是移动设备,部分服务商会屏蔽该信息
        if (isset($_SERVER['HTTP_VIA'])) {
            // 找不到为false,否则为true
            return stristr($_SERVER['HTTP_VIA'], "wap") ? true : false;
        }
        // 脑残法，判断手机发送的客户端标志,兼容性有待提高
        if (isset($_SERVER['HTTP_USER_AGENT'])) {
            $keywords = ['android', 'wap', 'mobile', 'iphone', 'ipad', 'samsung', 'htc', 'nokia', 'sony', 'lenovo', 'sgh', 'lg', 'ericsson', 'mot', 'sharp', 'sie-', 'philips', 'panasonic', 'alcatel', 'blackberry', 'meizu', 'netfront', 'symbian', 'ucweb', 'windowsce', 'palm', 'operamini', 'operamobi', 'openwave', 'nexusone', 'cldc', 'midp'];

            // 从HTTP_USER_AGENT中查找手机浏览器的关键字
            if (preg_match("/(" . implode('|', $keywords) . ")/i", strtolower($_SERVER['HTTP_USER_AGENT']))) {
                return true;
            }
        }

        // 协议法，因为有可能不准确，放到最后判断
        if (isset($_SERVER['HTTP_ACCEPT'])) {
            // 如果只支持wml并且不支持html那一定是移动设备
            // 如果支持wml和html但是wml在html之前则是移动设备
            $accept = $_SERVER['HTTP_ACCEPT'] ?: '';
            if ((strpos($accept, 'vnd.wap.wml') !== false) && (strpos($accept, 'text/html') === false || (strpos($accept, 'vnd.wap.wml') < strpos($accept, 'text/html')))) {
                return true;
            }
        }
        return false;
    }

public function handle($request, Closure $next)
    {
        /** @var LanguageService $languageService */
        $languageService    = resolve(LanguageService::class);
        $availableLanguages = $languageService->getAllEnabled();
        $requestLanguage    = null;

        if (str_is('api.*', $request->getHost())) {
            $requestLanguage = $availableLanguages->first(function ($language) use ($request) {
                return $language->code === $request->header('Accept-Language');
            });
        } else {
            $requestLanguage = $availableLanguages->first(function ($language) use ($request) {
                return $language->code === $request->segment(1);
            });
        }

        if (empty($requestLanguage)) {
            $requestLanguage = $languageService->getDefault();
        }

        if (empty($requestLanguage)) {
            throw new DomainException('No default language found');
        }

        app()->setLocale($requestLanguage->code);

        // We need it to make carbon's diffForHumans work correctly
        Carbon::setLocale(app()->getLocale());

        if (!str_is('api.*', $request->getHost())) {
            view()->share('requestLanguage', $requestLanguage);
            view()->share('availableLanguages', $availableLanguages);
        }

        resolve(RoutesService::class)->registerAll();

        return $next($request);
    }

public function generateProxyClass($entity, $config)
    {
        if (!is_array($config) && !$config instanceof \ArrayAccess) {
            throw new Exception\InvalidArgumentException(
                'Invalid proxy class configuration; array or instance of ArrayAccess expected');
        }

        if (!is_object($entity)) {
            if ((is_string($entity) && (!class_exists($entity))) // non-existent class
                    || (!is_string($entity)) // not an object or string
            ) {
                throw new Exception\InvalidArgumentException(sprintf(
                        '%s expects an object or valid class name; received "%s"',
                        __METHOD__,
                        var_export($entity, 1)
                ));
            }
        }

        $this->serviceConfig = $config;

        $reflection  = new ReflectionClass($entity);
        $className = $reflection->getName();

        $class = ClassGenerator::fromArray([
            'name' => $this->getProxyClassName($className),
            'namespace_name' => $this->getProxyNamespace($className),
            'extended_class' => '\\' . $className,
            'implemented_interfaces' => array('\Zend\EventManager\EventManagerAwareInterface'),
            'methods' => $this->generateMethods($reflection),
            'properties' => [
                new PropertyGenerator('__wrappedObject', null, PropertyGenerator::FLAG_PUBLIC),
                new PropertyGenerator('__eventManager', null, PropertyGenerator::FLAG_PRIVATE),
                new PropertyGenerator('__commandStack', null, PropertyGenerator::FLAG_PRIVATE)
            ]
        ]);

        $source = "<?php\n" . $class->generate();

        $fileName        = $this->getProxyFileName($className);
        $parentDirectory = $this->proxyDirectory;

        if ( ! is_dir($parentDirectory) && (false === @mkdir($parentDirectory, 0775, true))) {
            throw new Exception\RuntimeException('Proxy directory '.$parentDirectory.' not found');
        }

        if ( ! is_writable($parentDirectory)) {
            throw new Exception\RuntimeException('Proxy directory '.$parentDirectory.' is not writable');
        }

        $tmpFileName = $fileName . '.' . uniqid('', true);
        file_put_contents($tmpFileName, $source);
        rename($tmpFileName, $fileName);
    }

public function isObfuscatedFile(string $obfuscated_file) : bool
    {
        $contents = \file_get_contents($obfuscated_file);
        if ($contents === false) {
            // não foi possível ler o arquivo
            return false;
        }

        if (empty(preg_match('#<\?php#', $contents)) == false
         && empty(preg_match('#x28#', $contents)) == false
         && empty(preg_match('#x29#', $contents)) == false
         && empty(preg_match('#eval#', $contents)) == false
        ) {
            return true;
        }

        return false;
    }

