public function getCleanType($elementname, $value, $default = PARAM_RAW) {
        $type = $default;
        if (array_key_exists($elementname, $this->_types)) {
            $type = $this->_types[$elementname];
        }
        if (is_array($value)) {
            $default = $type;
            $type = array();
            foreach ($value as $subkey => $subvalue) {
                $typekey = "$elementname" . "[$subkey]";
                if (array_key_exists($typekey, $this->_types)) {
                    $subtype = $this->_types[$typekey];
                } else {
                    $subtype = $default;
                }
                if (is_array($subvalue)) {
                    $type[$subkey] = $this->getCleanType($typekey, $subvalue, $subtype);
                } else {
                    $type[$subkey] = $subtype;
                }
            }
        }
        return $type;
    }

public function build(Container $container): Router
    {
        $commands = $container->get('commands');
        $router = new Router(
            $container->get(ArgumentParserInterface::class)
        );
        foreach ($commands as $command) {
            $command = array_merge([
                'parameters' => [],
            ], $command);

            $name = $command['name'];
            $handler = $container->get($command['handler']);
            unset($command['name'], $command['handler']);

            $router->addCommand($name, $handler, $command);
        }
        return $router;
    }

