public static function preprocess($url_parsed) {
        if (($url_parsed['host'] === 'youtu.be')
            && preg_match('/^\/([a-zA-Z0-9\-_]+?)$/', $url_parsed['path'], $matches)
        ) {
            $params = self::parseParams($url_parsed);
            $params['vid'] = $matches[1];
            return array(
                'path_type' => 'video',
                'params' => &$params,
            );
        } elseif (preg_match('/^\/watch$/', $url_parsed['path'])) {
            $params = self::parseParams($url_parsed);
            if ($params == FALSE) return FALSE;
            if (!isset($params['vid']) || ($params['vid'] == FALSE)) return FALSE;
            return array(
                'path_type' => 'video',
                'params' => &$params,
            );
        } elseif (preg_match('/^\/v\/([a-zA-Z0-9\-_]+?)(&.+?|)(|\/)$/', $url_parsed['path'], $matches)) {
            $params = self::parseParams($url_parsed);
            $params['vid'] = $matches[1];
            if (!empty($matches[2])) {
                parse_str($matches[2], $embed_query);
                $params += $embed_query;
            }
            if (!isset($params['vid']) || ($params['vid'] == FALSE)) return FALSE;
            return array(
                'path_type' => 'video',
                'params' => &$params,
            );
        } elseif ((preg_match('/^\/view_play_list$/', $url_parsed['path'])) ||
            (preg_match('/^\/playlist$/', $url_parsed['path']))) {
            parse_str($url_parsed["query"], $query);
            $location = preg_replace('/([a-z]+?)\.youtube\.com/', '$1', strtolower($url_parsed["host"]));
            return array(
                'path' => $url_parsed['path'],
                'path_type' => 'playlist',
                'query' => &$query,
                'location' => $location,
            );
        }
        return FALSE;
    }

