public function getMeter($meterIdentifier)
    {
        // create cache key
        $item_key = $this->getCacheKey($meterIdentifier);

        // if not cached, go get it
        if (!($meter = $this->cacheService->retrieve($item_key))) {
            try {
                // find specific meter for company and login
                $meter = $this->meterStorage->getMeter($meterIdentifier);
            } catch (\Exception $e) {
                $meter = array();
            }

            // cache meter
            $this->cacheService->store($item_key, $meter, $this->cacheExpires);
        }

        return $meter;
    }

public static function upload($src, $dest, $useStreams = false)
	{
		// Ensure that the path is valid and clean
		$dest = Path::clean($dest);

		// Create the destination directory if it does not exist
		$baseDir = \dirname($dest);

		if (!is_dir($baseDir))
		{
			Folder::create($baseDir);
		}

		if ($useStreams)
		{
			$stream = Stream::getStream();

			if (!$stream->upload($src, $dest, null, false))
			{
				throw new FilesystemException(sprintf('%1$s(%2$s, %3$s): %4$s', __METHOD__, $src, $dest, $stream->getError()));
			}

			return true;
		}

		if (is_writable($baseDir) && move_uploaded_file($src, $dest))
		{
			// Short circuit to prevent file permission errors
			if (Path::setPermissions($dest))
			{
				return true;
			}

			throw new FilesystemException(__METHOD__ . ': Failed to change file permissions.');
		}

		throw new FilesystemException(__METHOD__ . ': Failed to move file.');
	}

