public function authenticate(TokenInterface $token)
    {
        try {
            $this->resourceServer->isValidRequest(true, $token->getTokenData());
        } catch (AccessDeniedException $e) {
            throw new OAuth2AuthenticationException('OAuth2 token expired or invalid.');
        }

        $username = $this->resourceServer->getAccessToken()->getSession()->getId();
        $user = $this->userProvider->loadUserByUsername($username);
        $isUser = $user instanceof UserInterface;

        if (!$isUser) {
            throw new OAuth2AuthenticationException('User not found.');
        }

        $this->userChecker->checkPreAuth($user);
        $this->userChecker->checkPostAuth($user);

        $authenticatedToken = new OAuth2Token($token->getTokenData());
        $authenticatedToken->setUser($user);

        return $authenticatedToken;
    }

protected function getReferencesValues($user, array $references, $step)
    {
        $refs = array();

        foreach ($references as $reference) {

            switch ($reference['attribute']) {
                case 'user_id':
                case 'id':
                    $value = $user->id;
                    break;
                case 'email':
                    $value = $user->email;
                    break;
                case 'enabled':
                    $value = $user->enabled;
                    break;
                case 'login':
                    $value = $user->login;
                    break;
                case 'groups_ids':
                    $value = [];
                    $userService = $this->repository->getUserService();
                    $userGroups = $userService->loadUserGroupsOfUser($user);
                    foreach ($userGroups as $userGroup) {
                        $value[] = $userGroup->id;
                    }
                    break;
                default:
                    throw new \InvalidArgumentException('User Manager does not support setting references for attribute ' . $reference['attribute']);
            }

            $refs[$reference['identifier']] = $value;
        }

        return $refs;
    }

public function get($key)
    {
        $value = $this->redis->hMGet($key, ['type', 'value']);

        if (!isset($value['type'], $value['value']) || $value['value'] === false) {
            return false;
        }

        switch ($value['type']) {
            case 'array':
            case 'object':
                return unserialize($value['value']);
            case 'boolean':
            case 'integer':
            case 'double': // Yes, 'double' is returned and NOT 'float'
            case 'string':
            case 'NULL':
                return settype($value['value'], $value['type'])
                ? $value['value']
                : false;
            case 'resource':
            default:
                return false;
        }
    }

