public function setTerms($terms, $reset = false)
    {
        if ($reset) {
            $this->searchTerms = array();
        }

        $searchTerms = array();
        if (!is_array($terms)) {
            $terms = explode(' ', $terms);
        }

        foreach ($terms as $term) {
            $words = explode(' ', $term);

            $searchTerms = array_merge($searchTerms, $words);
        }

        $this->searchTerms = array_merge($this->searchTerms, $searchTerms);

        return $this;
    }

