protected function enablePush()
    {
        if (! class_exists('\React\ZMQ\Context')) {
            $this->error('React/ZMQ dependency is required to enable push. Stopping server.', 1);
            die();
        }

        $context = new ZMQContext($this->loop);

        $this->pull = $context->getSocket(ZMQ::SOCKET_PULL, self::SOCKET_PULL_ID . '.' . App::environment());
        $this->pull->bind('tcp://127.0.0.1:' . $this->option('push-port'));
        $this->pull->on('message', [$this->Dispatcher, 'push']);

        $this->info('Push enabled on port <comment>[' . $this->option('push-port') . ']</comment>', 1);
    }

public function add_endpoints( $git, $endpoint ) {
		switch ( $git::$method ) {
			case 'projects':
				$endpoint = add_query_arg( 'per_page', '100', $endpoint );
				break;
			case 'meta':
			case 'tags':
			case 'branches':
			case 'download_link':
				break;
			case 'file':
			case 'changes':
			case 'readme':
				$endpoint = add_query_arg( 'ref', $git->type->branch, $endpoint );
				break;
			case 'translation':
				$endpoint = add_query_arg( 'ref', 'master', $endpoint );
				break;
			case 'release_asset':
				$endpoint = add_query_arg( 'job', $git->type->ci_job, $endpoint );
				break;
			default:
				break;
		}

		$endpoint = $this->add_access_token_endpoint( $git, $endpoint );

		/*
		 * If GitLab CE/Enterprise return this endpoint.
		 */
		if ( ! empty( $git->type->enterprise_api ) ) {
			return $git->type->enterprise_api . $endpoint;
		}

		return $endpoint;
	}

public static function registerClassesAndSave($transformersAndClasses) {
		self::start ();
		foreach ( $transformersAndClasses as $transformer => $class ) {
			self::registerClass ( $transformer, $class );
		}
		self::store ();
	}

