public static function createFromBase64($base64String): ?GUID
    {
        $bin = base64_decode($base64String, true);
        if (false === $bin) {
            return null;
        }

        if (!static::validate($bin)) {
            return null;
        }

        return new static($bin);
    }

public function getAvailableTransitions(Reference $ref, $state = null)
	{
		if ($state === null) {
			$state = $ref->state;
		}

		$available_transitions = array();

		foreach ($this->actions as $a => $action) {
			if (!empty($action['transitions'][$state]) && $this->isTransitionAllowed($ref, $a, $state)) {
				$available_transitions[] = $a;
			}
		}

		return $available_transitions;
	}

