public function create($class, $args = [])
    {
        $class = (string) $class;

        if (empty($class)) {
            throw new InvalidArgumentException(
                'Cannot create a migration from an empty class name!'
            );
        }

        if (!is_array($args)) {
            throw new InvalidArgumentException(
                'Argument "params" must be an array of parameters.'
            );
        }

        if (!empty($args)) {
            $class = new \ReflectionClass($class);
            $instance = $class->newInstanceArgs($args);
        } else {
            $instance = new $class();
        }

        return $instance;
    }

public function getDirtyRelationships(): array
    {
        $dirtyAggregates = [];

        foreach ($this->relationships as $relation) {
            foreach ($relation as $aggregate) {
                if (!$aggregate->exists() || $aggregate->isDirty() || count($aggregate->getDirtyRelationships()) > 0) {
                    $dirtyAggregates[] = $aggregate;
                }
            }
        }

        return $dirtyAggregates;
    }

public function formatAmount($amount, $currency = null)
    {
        return str_replace('.00', '', $this->moneyHelper->formatAmount($amount, $currency));
