protected static function throwParamException(
        array $params,
        string $key,
        \Throwable $exception
    ) {
        $message = $exception->getMessage();

        if (self::isDebug()) {
            echo(
                "\n<pre>\n"
                . "Param Error: " . $message
                . "\n key: {$key}"
                // . "\n params: " . Json::encode($params, JSON_PRETTY_PRINT, 3)
                . "\n params dump: " . var_export($params, true)
                . "\n</pre>\n"
            );
        }

        throw $exception;
    }

protected function _configWrite($key, $value, $merge = false)
    {
        if (is_string($key) && $value === null) {
            $this->_configDelete($key);

            return;
        }

        if ($merge) {
            $update = is_array($key) ? $key : [$key => $value];
            if ($merge === 'shallow') {
                $this->_config = array_merge($this->_config, Hash::expand($update));
            } else {
                $this->_config = Hash::merge($this->_config, Hash::expand($update));
            }

            return;
        }

        if (is_array($key)) {
            foreach ($key as $k => $val) {
                $this->_configWrite($k, $val);
            }

            return;
        }

        if (strpos($key, '.') === false) {
            $this->_config[$key] = $value;

            return;
        }

        $update =& $this->_config;
        $stack = explode('.', $key);

        foreach ($stack as $k) {
            if (!is_array($update)) {
                throw new Exception(sprintf('Cannot set %s value', $key));
            }

            if (!isset($update[$k])) {
                $update[$k] = [];
            }

            $update =& $update[$k];
        }

        $update = $value;
    }

