public static function modification($selector, array $config) {

    if (!empty($config['image'])) {
      $media = parent::getMediaQuery($config);

      $css[$media][$selector][] = 'background-image:url("' . $config['image'] . '")';
      $attributes[$media][$selector]['class'][] = 'modifiers-has-background';

      if (!empty($config['image_style'])) {

        switch ($config['image_style']) {

          case 'stretch':
            $css[$media][$selector][] = 'background-size:cover';
            break;

          case 'no-repeat':
          case 'repeat':
          case 'repeat-x':
          case 'repeat-y':
            $css[$media][$selector][] = 'background-repeat:' . $config['image_style'];
            break;
        }
      }
      if (!empty($config['image_position'])) {
        $position = str_replace('-', ' ', $config['image_position']);
        $css[$media][$selector][] = 'background-position:' . $position;
      }
      if (!empty($config['bgi_color_val'])) {
        $css[$media][$selector][] = 'background-color:' . $config['bgi_color_val'];
      }

      return new Modification($css, [], [], $attributes);
    }
    return NULL;
  }

public function loadFromWeChatAction($req)
    {
        $account = wei()->wechatAccount->getCurrentAccount();
        $api = $account->createApiService();

        $now = date('Y-m-d H:i:s');
        $db = wei()->db;
        $table = $db->getTable('weChatMenu');
        $result = $api->getMenu();

        if (!$result) {
            return $this->err('微信返回消息：' . $api->getMessage(), $api->getCode());
        }

        // 构造存入数据库的二维数组
        $menus = [];
        $sort = 1;

        foreach ($result['menu']['button'] as $button) {
            $parentId = wei()->seq();
            $menus[] = [
                'id' => $parentId,
                'parentId' => 0,
                'name' => $button['name'],
                'linkTo' => json_encode($this->createLinkToFromWeChatButton($button)),
                'sort' => $sort++,
                'accountId' => $req['accountId'],
                'createTime' => $now,
                'createUser' => $this->curUser['id'],
                'updateTime' => $now,
                'updateUser' => $this->curUser['id'],
            ];

            $subSort = 1;
            foreach ($button['sub_button'] as $subButton) {
                $menus[] = [
                    'id' => wei()->seq(),
                    'parentId' => $parentId,
                    'name' => $subButton['name'],
                    'linkTo' => json_encode($this->createLinkToFromWeChatButton($subButton)),
                    'sort' => $subSort++,
                    'accountId' => $req['accountId'],
                    'createTime' => $now,
                    'createUser' => $this->curUser['id'],
                    'updateTime' => $now,
                    'updateUser' => $this->curUser['id'],
                ];
            }
        }

        // 取出原来的菜单,记录到日志
        $origMenus = wei()->weChatMenu()->fetchAll(['accountId' => $req['accountId']]);
        $this->logger->info($origMenus);

        // 清空原来的菜单
        wei()->weChatMenu()->delete(['accountId' => $req['accountId']]);

        // 菜单数据插入数据表
        $db->batchInsert($table, $menus);

        return $this->suc();
    }

protected static function formatDate($date)
    {
        $d = \DateTime::createFromFormat('Y-m-d', $date);
        if (!$d) {
            $d = \DateTime::createFromFormat('Y-m-d H:i:s', $date);
        }
        return ($d ? $d->format('d/m/Y') : $date);
    }

protected function finalize(TaskConfiguration $taskConfiguration): void
    {
        $task = $taskConfiguration->getTask();
        if ($task instanceof FinalizableTaskInterface) {
            $this->taskConfiguration = $taskConfiguration;
            $state = $taskConfiguration->getState();
            try {
                $task->finalize($taskConfiguration->getState());
            } catch (\Throwable $e) {
                $logContext = ['exception' => $e];
                $this->taskLogger->critical($e->getMessage(), $logContext);
                $state->stop($e);
            }
            $this->handleState($state);
            $this->taskConfiguration = null;
        }
    }

