public function render()
    {
        try {
            $this->vars['all'] = $this->loadData()['all'];
            $this->vars['rows'] = $this->loadData()['user_rows'];
            $this->vars['users'] = $this->loadData()['users'];

        } catch (Exception $ex) {
            $this->vars['error'] = $ex->getMessage();
            $this->vars['all'] = 0;
            $this->vars['users'] = [];
            $this->vars['rows'] = [];
        }

