private function resolveController(): string
    {
        if (!empty($this->routeParams[0])) {
            $controllerName = implode('', array_map('ucfirst', explode('-', $this->routeParams[0])));

            return $this->configuration->getControllerNamespace() . $controllerName . 'Controller';
        }

        return $this->configuration->getControllerNamespace() . $this->configuration->getDefaultController() . 'Controller';
    }

function multiply($x)
    {
        switch (MATH_BIGINTEGER_MODE) {
            case self::MODE_GMP:
                $temp = new static();
                $temp->value = gmp_mul($this->value, $x->value);

                return $this->_normalize($temp);
            case self::MODE_BCMATH:
                $temp = new static();
                $temp->value = bcmul($this->value, $x->value, 0);

                return $this->_normalize($temp);
        }

        $temp = $this->_multiply($this->value, $this->is_negative, $x->value, $x->is_negative);

        $product = new static();
        $product->value = $temp[self::VALUE];
        $product->is_negative = $temp[self::SIGN];

        return $this->_normalize($product);
    }

public function filter(callable $callback = null)
    {
        if ($callback) {
            return new static($this->manager, array_filter($this->divisions, $callback));
        }

        return new static($this->manager, array_filter($this->divisions));
    }

