function rule_match_page_type( $match, $rule, $options )
	{
		// validation
		if( !$options['post_id'] )
		{
			return false;
		}

		$post = get_post( $options['post_id'] );

        if( $rule['value'] == 'front_page')
        {

	        $front_page = (int) get_option('page_on_front');


	        if($rule['operator'] == "==")
	        {
	        	$match = ( $front_page == $post->ID );
	        }
	        elseif($rule['operator'] == "!=")
	        {
	        	$match = ( $front_page != $post->ID );
	        }

        }
        elseif( $rule['value'] == 'posts_page')
        {

	        $posts_page = (int) get_option('page_for_posts');


	        if($rule['operator'] == "==")
	        {
	        	$match = ( $posts_page == $post->ID );
	        }
	        elseif($rule['operator'] == "!=")
	        {
	        	$match = ( $posts_page != $post->ID );
	        }

        }
        elseif( $rule['value'] == 'top_level')
        {
        	$post_parent = $post->post_parent;
        	if( $options['page_parent'] )
        	{
	        	$post_parent = $options['page_parent'];
        	}


	        if($rule['operator'] == "==")
	        {
	        	$match = ( $post_parent == 0 );
	        }
	        elseif($rule['operator'] == "!=")
	        {
	        	$match = ( $post_parent != 0 );
	        }

        }
        elseif( $rule['value'] == 'parent')
        {

        	$children = get_pages(array(
        		'post_type' => $post->post_type,
        		'child_of' =>  $post->ID,
        	));


	        if($rule['operator'] == "==")
	        {
	        	$match = ( count($children) > 0 );
	        }
	        elseif($rule['operator'] == "!=")
	        {
	        	$match = ( count($children) == 0 );
	        }

        }
        elseif( $rule['value'] == 'child')
        {

        	$post_parent = $post->post_parent;
        	if( $options['page_parent'] )
        	{
	        	$post_parent = $options['page_parent'];
        	}


	        if($rule['operator'] == "==")
	        {
	        	$match = ( $post_parent != 0 );
	        }
	        elseif($rule['operator'] == "!=")
	        {
	        	$match = ( $post_parent == 0 );
	        }

        }

        return $match;

	}

protected function formatResponse() : string {
        $responses = array();

        foreach (func_get_args() as $response) {
            $responses = array_merge($responses, (array) $response);
        }

        return array_to_newlines($responses);
    }

protected static function getAllParams() {
        if ($_SERVER['REQUEST_METHOD'] == 'PUT' || $_SERVER['REQUEST_METHOD'] == 'DELETE') {

            $input = file_get_contents('php://input');

            $encoded_data = array();

            if (isset($_SERVER['CONTENT_TYPE'])) {
                switch ($_SERVER['CONTENT_TYPE']) {
                    case 'application/x-www-form-urlencoded':
                        parse_str($input, $encoded_data);
                        break;
                    case 'application/json':
                        $encoded_data = json_decode($input);
                        break;
                    default :
                        $encoded_data = parse_raw_http_request($input);
                        break;
                }
            }

            if ($encoded_data) {
                foreach ($encoded_data as $key => $val) {
                    $_REQUEST[$key] = $val;
                }
            }
        }

        return $_REQUEST;
    }

public function schemaValidate($filename)
    {
        if (!is_readable($filename)) {
            throw new \DOMException("Schema file is not readable: $filename");
        }

        $user_error_handling = $this->enableErrorHandling();

        $success = parent::schemaValidate($filename);

        $this->handleErrors(
            'Validating the document failed. Details are:' . PHP_EOL . PHP_EOL,
            PHP_EOL . 'Please fix the mentioned errors or use another schema file.',
            $user_error_handling
        );

        return $success;
    }

