function insertFile( $path, $sqlFile, $usePathType = true )
    {
        $type = $this->databaseName();

        if ( $usePathType )
            $sqlFileName = eZDir::path( array( $path, $type, $sqlFile ) );
        else
            $sqlFileName = eZDir::path( array( $path, $sqlFile ) );
        if ( !file_exists( $sqlFileName ) )
        {
            eZDebug::writeError( "File not found: $sqlFileName", __METHOD__ );
            return false;
        }
        $sqlFileHandler = fopen( $sqlFileName, 'rb' );
        $buffer = '';
        $done = false;
        while ( count( ( $sqlArray = $this->prepareSqlQuery( $sqlFileHandler, $buffer ) ) ) > 0 )
        {
            // Turn unneccessary SQL debug output off
            $oldOutputSQL = $this->OutputSQL;
            $this->OutputSQL = false;
            if ( $sqlArray && is_array( $sqlArray ) )
            {
                $done = true;
                foreach( $sqlArray as $singleQuery )
                {
                    $singleQuery = preg_replace( "/\n|\r\n|\r/", " ", $singleQuery );
                    if ( preg_match( "#^ */(.+)$#", $singleQuery, $matches ) )
                    {
                        $singleQuery = $matches[1];
                    }
                    if ( trim( $singleQuery ) != "" )
                    {
//                    eZDebug::writeDebug( $singleQuery );
                        $this->query( trim( $singleQuery ) );
                        if ( $this->errorNumber() )
                        {
                            return false;
                        }
                    }
                }

            }
            $this->OutputSQL = $oldOutputSQL;
        }
        return $done;

    }

private function portFromFallback($path, $newpath)
	{
		$buffer = $this->fallback->readStream($path);

		if (false === $buffer) {
			return false;
		}

		$result = $this->mainAdapter->writeStream($newpath, $buffer['stream'], []);

		if (\is_resource($buffer['stream'])) {
			\fclose($buffer['stream']);
		}

		return (false !== $result);
	}

public function check($url, $must = false)
    {
        // 自动检测域名路由
        $domain = $this->checkDomain();

        $url = str_replace($this->config['app.pathinfo_depr'], '|', $url);

        $completeMatch = $this->config['app.route_complete_match'];

        $result = $domain->check($url, $completeMatch);

        if ($result) {
            $re =  array_merge($result, ['is_route' => true]);
            return $re;
        } elseif ($must) {
            // 强制路由不匹配则抛出异常
            throw new NotFoundHttpException('强制路由,不匹配');
        } else {
            // 检测跨域路由
//            if (!empty($this->cross)) {
//                $result = $this->cross->check($this->request, $url, $completeMatch);
//            }
//
//            if (false !== $result) {
//                // 路由匹配
//                return $result;
//            }

            // 默认路由解析
            $re = new UrlDispatch($this->group, $url, [
                'auto_search' => $this->autoSearchController,
            ]);

            return array_merge($re->init(), ['is_route' => false]);
        }
    }

