public function prepareForController($assets, $type)
	{
		$controller_url = $this->cdn ? $this->cdn . '/' : '/';
		$controller_url .= $this->route . '/' . $type;
		$controller_url .= '?c=' . urlencode($this->name);

		$links = array();

		foreach ($assets as &$asset) {
			$attributes = $asset['attributes'];
			unset($asset['attributes']);
			unset($asset['ext']);

			if (empty($asset['dependencies'])) {
				unset($asset['dependencies']);
			}

			if (!$this->combine) {
				$url = $controller_url . '&files=' . base64_encode(json_encode(array($asset)));
				$url .= $this->version ? '&v=' . $this->version : '';

				if ('style' == $type) {
					$links[] = HTML::style($url, $attributes);
				}
				else {
					$links[] = HTML::script($url, $attributes);
				}
			}
		}

		if ($this->combine) {
			$url = $controller_url . '&files=' . base64_encode(json_encode($assets));
			$url .= $this->version ? '&v=' . $this->version : '';

			if ('style' == $type) {
				$links[] = HTML::style($url);
			}
			else {
				$links[] = HTML::script($url);
			}
		}

		return implode('', $links);
	}

public function open($savePath, $sessionName)
    {
        $this->kind = $sessionName;
        if (preg_match(self::NAMESPACE_ALLOWED_PATTERN, $savePath) !== 1 ||
            preg_match(self::NAMESPACE_RESERVED_PATTERN, $savePath) === 1) {
            throw new InvalidArgumentException(
                sprintf('The given save_path "%s" not allowed', $savePath)
            );
        }
        $this->namespaceId = $savePath;
        $this->transaction = $this->datastore->transaction();
        return true;
    }

public static function courseToString($arrCourse,$long = false) {
		//add title of course ('Klasse', 'Tutorium', ...)
		if($long) {
			$strName = $arrCourse['title'] . ' ';
		}
		else $strName = '';

		//add grade&formSelector / grade&teacher
		if($arrCourse['grade'] <= 10) {
			$strName .= $arrCourse['grade'] . '/' . $arrCourse['formSelector'];
		}
		elseif(static::getGOSTGrade($arrCourse['graduation'])) {
			if($arrCourse['leader'] == 0) {
				$strName .= static::getGOSTGrade($arrCourse['graduation']);
			}
			elseif($arrCourse['leader'] != 0) {
				static::teacherList();
				$strName .= static::getGOSTGrade($arrCourse['graduation']) . ' ' . static::$arrTeachers[$arrCourse['leader']]['acronym'];
			}
		}
		else return false;
		return $strName;
	}

