function match_field_groups( $return, $options )
	{

		// vars
		$defaults = array(
			'post_id' => 0,
			'post_type' => 0,
			'page_template' => 0,
			'page_parent' => 0,
			'page_type' => 0,
			'post_category' => array(),
			'post_format' => 0,
			'taxonomy' => array(),
			'ef_taxonomy' => 0,
			'ef_user' => 0,
			'ef_media' => 0,
			'lang' => 0,
			'ajax' => false
		);


		// merge in $options
		$options = array_merge($defaults, $options);


		// Parse values
		$options = apply_filters( 'acf/parse_types', $options );


		// WPML
		if( defined('ICL_LANGUAGE_CODE') )
		{
			$options['lang'] = ICL_LANGUAGE_CODE;

			//global $sitepress;
			//$sitepress->switch_lang( $options['lang'] );
		}


		// find all acf objects
		$acfs = apply_filters('acf/get_field_groups', array());


		// blank array to hold acfs
		$return = array();


		if( $acfs )
		{
			foreach( $acfs as $acf )
			{
				// load location
				$acf['location'] = apply_filters('acf/field_group/get_location', array(), $acf['id']);


				// vars
				$add_box = false;


				foreach( $acf['location'] as $group_id => $group )
				{
					// start of as true, this way, any rule that doesn't match will cause this varaible to false
					$match_group = true;

					if( is_array($group) )
					{
						foreach( $group as $rule_id => $rule )
						{
							// Hack for ef_media => now post_type = attachment
							if( $rule['param'] == 'ef_media' )
							{
								$rule['param'] = 'post_type';
								$rule['value'] = 'attachment';
							}


							// $match = true / false
							$match = apply_filters( 'acf/location/rule_match/' . $rule['param'] , false, $rule, $options );

							if( !$match )
							{
								$match_group = false;
							}

						}
					}


					// all rules must havematched!
					if( $match_group )
					{
						$add_box = true;
					}

				}


				// add ID to array	
				if( $add_box )
				{
					$return[] = $acf['id'];

				}

			}
		}


		return $return;
	}

protected static function resolveUrl($url)
    {
        $url = trim($url);
        if (strlen($url)) {
            if (preg_match('%^https?\:\/\/%', $url)) {
                return $url;
            }
            $absScript = GeneralUtility::getFileAbsFileName($url);
            if (is_file($absScript)) {
                return substr($absScript, strlen(PATH_site));
            }
        }

        return null;
    }

