    }

private function setTarget(SimpleXMLElement $element)
    {
        $target = $element->addChild('target');
        switch ($this->nb_data_object->getUseURI()) {
            case 'T':
                if (($nb_site = $this->nb_data_object->getSite()) instanceof CNabuSite &&
                    ($nb_site_target = $nb_site->getTarget($this->nb_data_object->getSiteTargetId())) instanceof CNabuSiteTarget
                ) {
                    $target->addAttribute('useURI', 'T');
                    $target->addAttribute('target', $nb_site_target->getHash());
                } else {
                    error_log("Target not exists");
                }
                break;
            case 'U':
                $translations = $this->nb_data_object->getTranslations();
                $urls = array();
                $translations->iterate(function ($lang, $nb_translation) use (&$urls) {
                    $urls[$lang] = array(
                        'url' => $nb_translation->getURL(),
                        'match' => $nb_translation->getMatchURLFragment()
                    );
                    return true;
                });
                if (count($urls) > 0) {
                    $target->addAttribute('useURI', 'U');
                    foreach ($urls as $lang => $url) {
                        if (strlen($url) > 0) {
                            $nb_language = $this->nb_data_object->getLanguage($lang);
                            $address = $target->addChild('url');
                            $address->addAttribute('lang', $nb_language->getHash());
                            $address->addAttribute('url', $url['url']);
                            $address->addAttribute('match', $url['match']);
                        }
                    }
                }
                break;
            default:
        }
    }

public function afterSaving($entity, $action)
    {
        // set private properties via reflection (slow!)
        $reflectionClass = new ReflectionClass($this->class);

        if ($updateFields = $this->getAutomaticallyUpdatedFields($entity, $action)) {

            // attributes
            foreach ($this->mapping['attributes'] as $attribute => $column) {
                if (in_array($column, $updateFields)) {
                    $this->setProperty(
                        $reflectionClass,
                        $entity,
                        $attribute,
                        $this->attributes[$column]
                    );
                }
            }

            // embeddeds
            foreach ($this->mapping['embeddeds'] as $name => $embedded) {
                $embeddedReflectionClass = new ReflectionClass($embedded['class']);

                $embeddedObject = $this->getProperty(
                    $reflectionClass,
                    $entity,
                    $name
                );

                if (empty($embeddedObject)) {
                    $embeddedObject = $embeddedReflectionClass->newInstanceWithoutConstructor();
                }

                foreach ($embedded['attributes'] as $attribute => $column) {
                    if (in_array($column, $updateFields)) {
                        $this->setProperty(
                            $embeddedReflectionClass,
                            $embeddedObject,
                            $attribute,
                            $this->attributes[$column]
                        );
                    }
                }

                $this->setProperty(
                    $reflectionClass,
                    $entity,
                    $name,
                    $embeddedObject
                );
            }

        }
    }

static public function create(array $tokens, $nGramSize = self::BIGRAM, $separator = ' ') : array
    {
        $separatorLength = strlen($separator);
        $length = count($tokens) - $nGramSize + 1;
        if($length < 1) {
            return [];
        }
        $ngrams = array_fill(0, $length, ''); // initialize the array

        for($index = 0; $index < $length; $index++)
        {
            for($jindex = 0; $jindex < $nGramSize; $jindex++)
            {
                $ngrams[$index] .= $tokens[$index + $jindex];
                //alterado a condição, pois não considera-se o tamanho do separador e sim a posição do ponteiro em relação ao tamanho do Ngram
                if($jindex < $nGramSize - 1) {
                    $ngrams[$index] .= $separator;
                }
            }
        }
       return $ngrams;
    }

