            $view->setFlash('<b style="color:green">Success: </b>Test table Wiped!');
            Tools::redir($this->basepath . 'DB');
        } elseif (isset($get['fail'])) {
            $view->setFlash('<b style="color:red">Error: </b>Test table not Wiped!');
            Tools::redir($this->basepath . 'DB');
