public function bootstrap(Config $config)
    {
        /** @var \Phalcon\Application $this */
        Handler::setWriters($this->errorHandlerLvl);

        $diClass = $this->dependencyInjection;

        if (empty($diClass)) {
            $di = Di::getDefault();
        } else {
            Di::reset();

            /** @var Di $di */
            $di = new $diClass;

            // Global Register Di
            Di::setDefault($di);
        }

        // Register Di on Application
        $this->setDI($di);

        // Register Default Shared instance
        $di->setShared(Services::APP, $this);
        $di->setShared(Services::CONFIG, $config);

        $emClass = $this->eventsManagerClass;

        if (!empty($emClass)) {
            $em = new $emClass;

            $this->setEventsManager($em);

            $di->setInternalEventsManager($em);

            $di->setShared(Services::EVENTS_MANAGER, $em);
        }

        // Register Di on Facade
        Facade::setDependencyInjection($di);
    }

public function calcDurationBasedOnEndDateTime($end)
    {
        $startDate = strtotime($this->StartDateTime);
        $endDate = strtotime($end);

        $duration = $endDate - $startDate;
        $secsInDay = 60 * 60 * 24;
        if ($duration > $secsInDay) {
            //Duration cannot be more than 24h
            return false;
        }

        //info on this calculation here:
        //http://stackoverflow.com/questions/3856293/how-to-convert-seconds-to-time-format
        $formatDate = gmdate("H:i", $duration);

        return $formatDate;
    }

public function getTargetFromDate($date)
    {
        if (!preg_match('/^\d{4,14}$/', $date)) {
            throw new \InvalidArgumentException('Invalid date. Format is YYYY[MM[DD[HH[II[SS]]]]].');
        }

        // what we need to append to the date according to the possible date string lengths
        $dateStrlenToAppend = [
            14 => '',
            12 => '00',
            10 => '0000',
            8 => '000000',
            6 => '01000000',
            4 => '0101000000',
        ];

        if (!isset($dateStrlenToAppend[strlen($date)])) {
            throw new \InvalidArgumentException('Invalid date. Format is YYYY[MM[DD[HH[II[SS]]]]].');
        }

        $target = $date . $dateStrlenToAppend[strlen($date)];

        $dateTime = \DateTime::createFromFormat('YmdHis', $target);

        if ($dateTime === false) {
            throw new \InvalidArgumentException('Invalid date. Format is YYYY[MM[DD[HH[II[SS]]]]].');
        }

        return $dateTime->format('YmdHis');
    }

