protected function execute(InputInterface $input, OutputInterface $output)
    {
        $processBuilder = ProcessBuilder::create([
            'drush',
            '--root=' . Platform::webDir(),
            '--uri=' . Platform::getUri()
        ]);
        foreach ($input->getArgument('cmd') as $argument) {
            $processBuilder->add($argument);
        }
        foreach ($input->getOption('drush_option') as $option) {
            $processBuilder->add($option);
        }

        if ($output->getVerbosity() > $output::VERBOSITY_NORMAL) {
            $output->writeln('Running drush command: <info>' . $processBuilder->getProcess()->getCommandLine() . '</info>');
        }

        passthru($processBuilder->getProcess()->getCommandLine());
    }

protected function doInsert(ConnectionInterface $con)
    {
        $modifiedColumns = array();
        $index = 0;

        $this->modifiedColumns[IndexEngineDriverConfigurationTableMap::ID] = true;
        if (null !== $this->id) {
            throw new PropelException('Cannot insert a value for auto-increment primary key ('.IndexEngineDriverConfigurationTableMap::ID.')');
        }

         // check the columns in natural order for more readable SQL queries
        if ($this->isColumnModified(IndexEngineDriverConfigurationTableMap::ID)) {
            $modifiedColumns[':p'.$index++]  = 'ID';
        }
        if ($this->isColumnModified(IndexEngineDriverConfigurationTableMap::CODE)) {
            $modifiedColumns[':p'.$index++]  = 'CODE';
        }
        if ($this->isColumnModified(IndexEngineDriverConfigurationTableMap::DRIVER_CODE)) {
            $modifiedColumns[':p'.$index++]  = 'DRIVER_CODE';
        }
        if ($this->isColumnModified(IndexEngineDriverConfigurationTableMap::TITLE)) {
            $modifiedColumns[':p'.$index++]  = 'TITLE';
        }
        if ($this->isColumnModified(IndexEngineDriverConfigurationTableMap::SERIALIZED_CONFIGURATION)) {
            $modifiedColumns[':p'.$index++]  = 'SERIALIZED_CONFIGURATION';
        }

        $sql = sprintf(
            'INSERT INTO index_engine_driver_configuration (%s) VALUES (%s)',
            implode(', ', $modifiedColumns),
            implode(', ', array_keys($modifiedColumns))
        );

        try {
            $stmt = $con->prepare($sql);
            foreach ($modifiedColumns as $identifier => $columnName) {
                switch ($columnName) {
                    case 'ID':
                        $stmt->bindValue($identifier, $this->id, PDO::PARAM_INT);
                        break;
                    case 'CODE':
                        $stmt->bindValue($identifier, $this->code, PDO::PARAM_STR);
                        break;
                    case 'DRIVER_CODE':
                        $stmt->bindValue($identifier, $this->driver_code, PDO::PARAM_STR);
                        break;
                    case 'TITLE':
                        $stmt->bindValue($identifier, $this->title, PDO::PARAM_STR);
                        break;
                    case 'SERIALIZED_CONFIGURATION':
                        $stmt->bindValue($identifier, $this->serialized_configuration, PDO::PARAM_STR);
                        break;
                }
            }
            $stmt->execute();
        } catch (Exception $e) {
            Propel::log($e->getMessage(), Propel::LOG_ERR);
            throw new PropelException(sprintf('Unable to execute INSERT statement [%s]', $sql), 0, $e);
        }

        try {
            $pk = $con->lastInsertId();
        } catch (Exception $e) {
            throw new PropelException('Unable to get autoincrement id.', 0, $e);
        }
        $this->setId($pk);

        $this->setNew(false);
    }

