public function collect(Request $request, Response $response, \Exception $exception = null)
    {
        $this->data = array(
            'app_name'         => $this->name,
            'app_version'      => $this->version,
            'token'            => $response->headers->get('X-Debug-Token'),
            'BackBee_version'  => BBApplication::VERSION,
            'name'             => $this->kernel->getApplication()->getSite() ? $this->kernel->getApplication()->getSite()->getLabel() : 'n/a',
            'debug'            => isset($this->kernel) ? $this->kernel->getApplication()->isDebugMode() : 'n/a',
            'env'              => isset($this->kernel) ? $this->kernel->getApplication()->getEnvironment() : 'n/a',
            'context'          => isset($this->kernel) ? $this->kernel->getApplication()->getContext() : 'n/a',
            'php_version'      => PHP_VERSION,
            'xdebug_enabled'   => extension_loaded('xdebug'),
            'eaccel_enabled'   => extension_loaded('eaccelerator') && ini_get('eaccelerator.enable'),
            'apc_enabled'      => extension_loaded('apc') && ini_get('apc.enabled'),
            'xcache_enabled'   => extension_loaded('xcache') && ini_get('xcache.cacher'),
            'wincache_enabled' => extension_loaded('wincache') && ini_get('wincache.ocenabled'),
            'bundles'          => array(),
            'sapi_name'        => php_sapi_name(),
        );

        if (isset($this->kernel)) {
            foreach ($this->kernel->getApplication()->getBundles() as $name => $bundle) {
                $this->data['bundles'][$name] = $bundle->getBaseDirectory();
            }
        }
    }

public static function deleteInternal($id, $record, $params = [])
    {
        if (empty($record)) {
            throw new BadRequestException('There are no fields in the record to create . ');
        }

        if (empty($id)) {
            //Todo:perform logging below
            //Log::error( 'Update request with no id supplied: ' . print_r( $record, true ) );
            throw new BadRequestException('Identifying field "id" can not be empty for update request . ');
        }

        $userId = SessionUtility::getCurrentUserId();
        $model = static::whereUserId($userId)->whereName($id)->first();

        if (!$model instanceof Model) {
            throw new NotFoundException("Record with identifier '$id' not found.");
        }

        try {
            $result = static::buildResult($model, $params);
            $model->delete();

            return $result;
        } catch (\Exception $ex) {
            throw new InternalServerErrorException('Failed to delete resource: ' . $ex->getMessage());
        }
    }

