protected function interpolate($message, array $placeholders = [])
    {
        if ($placeholders) {
            $replace = [];
            foreach ($placeholders as $key => $val) {
                $replace['{' . $key . '}'] = $val;
            }

            return strtr($message, $replace);
        } else {
            return $message;
        }
    }

