            $newRoute = $app["router.newRoute"];
            $newRoute->set(
                ($route["uri"] ?? null),
                ($route["method"] ?? Route::METHOD_GET),
                ($route["action"] ?? null)
            );

            foreach (["beforeDispatch", "afterDispatch"] as $type) {
                if (isset($routeDefinition[$type])) {
                    $newRoute->setHook($routeDefinition[$type], $type === "afterDispatch");
