protected function execute(InputInterface $input, OutputInterface $output)
    {
        $userName = $input->getArgument('username');

        $this->io->title("Resetting password for user '$userName'");
        $ask = !$input->getOption('no-interaction');
        $question = new ConfirmationQuestion("<question>Are you sure you want to reset the password for '$userName'?</question>", false);
        if ($ask && !$this->io->askQuestion($question)) {
            return 0;
        }

        // Boot all service providers manually as, we're not handling a request
        $this->app->boot();
        $password = $this->app['access_control.password']->setRandomPassword($userName);
        if ($password === false) {
            $this->io->error("Error no such user $userName");

            return 1;
        }
        $this->io->success("New password for $userName is $password");

        return 0;
    }

private static function fromInterval($value)
    {
        if (is_null($value)) {
            return null;
        }
        $res = preg_match(
            "/(?P<sign>\-)?(?:(?P<years>\d+) years? ?)?(?:(?P<months>\d+) mons? ?)?(?:(?P<days>\d+) days? ?)?" .
            "(?:(?P<h>\d+):(?P<m>\d+):(?P<s>\d+))?(?:\.(?P<ms>\d+))?/",
            $value,
            $match
        );
        if (!$res) {
            throw new Exception('Malformed interval');
        }
        $match += ['years' => 0, 'months' => 0, 'days' => 0, 'h' => 0, 'm' => 0, 's' => 0];

        $res = $match['years'] * 31557600
            + $match['months'] * 2592000
            + $match['days'] * 86400
            + $match['h'] * 3600
            + $match['m'] * 60
            + $match['s'];

        if (!empty($match['ms'])) {
            $res = floatval($res) + floatval($match['ms'] / intval('1' . str_repeat('0', strlen($match['ms']))));
        }

        if (isset($match['sign']) && $match['sign'] == '-') {
            $res *= -1;
        }

        return $res;
    }

public function errorHandler($errno, $errstr, $errfile, $errline, $errcontext)
    {
        // Don't throw exception if error reporting is switched off
        if (error_reporting() == 0) {
            return;
        }
        // Only throw exceptions for errors we are asking for
        if (error_reporting() & $errno) {

            $exception = new ErrorException($errstr, 0, $errno, $errfile, $errline);
            if ($this->throwErrorExceptions) {
                throw $exception;
            } else {
                $this->fb($exception);
            }
        }
    }

