private function _isContainPrefixSelector($node)
    {
        if ($node->hasAttribute($this->_attrName)) {
            $attr = $node->getAttribute($this->_attrName);
            $len = strlen($this->_value);
            if ($len > 0) {
                $pos = stripos($attr, $this->_value);
