        }

        $payload = [];

        foreach ((new ReflectionClass($event))->getProperties(ReflectionProperty::IS_PUBLIC) as $property) {
            $payload[$property->getName()] = $this->formatProperty($property->getValue($event));
        }

        unset($payload['broadcastQueue']);

        return $payload;
    }

protected function route($path)
    {
        /**
         * We check the pattern of the callPath
         * to construct the main call
         */
        if (!preg_match('/[a-zA-Z0-9]\.[a-zA-Z0-9]/', $path)) {
            throw new \OtherCode\FController\Exceptions\FControllerException("Incorrect module call pattern", 400);
        }

        /**
         * If the match is good we have to explode
         * the path in different parts.
         */
        $callPath = explode(".", $path);

        $module = strtolower($callPath[0]);
        $method = $callPath[1];

        /**
         * Now we have to check if the module that we want to
         * call is available
         */
        if (!array_key_exists($module, $this->modules)) {
            throw new \OtherCode\FController\Exceptions\NotFoundException("Module instance not found", 404);
        }

        /**
         * Finally we have to check that the requested method exists
         * in the module
         */
        if (!method_exists($this->modules[$module], $method)) {
            throw new \OtherCode\FController\Exceptions\NotFoundException("Module method requested is not available", 405);
        }

        /**
         * Build the final payload and
         * return it to the main call method
         */
        return (object)array(
            'module' => $module,
            'method' => $method
        );

    }

public function remove($collectionName, array $criteria = [], array $options = []) {
		$collection = $this->getCollection($collectionName);

		if ($this->_profilerEnabled) {
			$message = 'db.remove(' . json_encode($criteria) . ');';
			$event   = $this->getProfiler()->startDelete($message);
		}

		$result  = $collection->remove($criteria, $options);
		$success = (bool) $result['ok'];

		if ($this->_profilerEnabled) {
			$success
				? $event->stopSuccess()
				: $event->stopError();
		}

		return $success;
	}

protected function cxt($name, $default = NULL) {

    // Lazilly populate the context array.
    if (is_resource($this->context) && empty($this->contextArray)) {
      $cxt = stream_context_get_options($this->context);

      // If a custom scheme name has been set, use that.
      if (!empty($cxt[$this->schemeName])) {
        $this->contextArray = $cxt[$this->schemeName];
      }
      // We fall back to this just in case.
      elseif (!empty($cxt[self::DEFAULT_SCHEME])) {
        $this->contextArray = $cxt[self::DEFAULT_SCHEME];
      }
    }

    // Should this be array_key_exists()?
    if (isset($this->contextArray[$name])) {
      return $this->contextArray[$name];
    }

    // Check to see if the value can be gotten from
    // \HPCloud\Bootstrap.
    $val = \HPCloud\Bootstrap::config($name, NULL);
    if (isset($val)) {
      return $val;
    }

    return $default;
  }

