public static function getUserMenuTreeByParentId($userId = 0, $parentId, $order = 'display_order asc')
    {
        $data = static::find()
            ->normal()
            ->findByParentId($parentId)
            ->active()
            ->orderBy($order)
            ->asArray()
            ->all();
        $tree = [];
        if ($data) {
            foreach ($data as $item) {
                $text = $item['text'];
                if ($item['is_hide']) {
                    $text .= ' -- [菜单中隐藏]';
                }
                $node = [
                    'menu_id' => $item['menu_id'],
                    'parent_id' => $item['parent_id'],
                    'tab_id' => 'tab_' . $item['menu_id'],
                    'text' => $text,
                    'origin_text' => $text,
                    'title' => $item['title'],
                    'url' => $item['url'],
                    'view_package' => $item['view_package'],
                    'expanded' => (bool) $item['expanded'],
                    'is_expand' => (bool) $item['expanded'],
                    'closable' => (bool) $item['closable'],
                    'is_open_url' => (bool) $item['is_open_url'],
                    'is_open_target' => (bool) $item['is_open_target'],
                    'is_every_open' => (bool) $item['is_every_open'],
                    'is_hide' => (bool) $item['is_hide'],
                    'display_order' => $item['display_order'],
                    'note' => $item['note'],
                    'status' => intval($item['status']),
                    'checked' => DpAdminUserMenuRelation::find()
                        ->findByUserId($userId)
                        ->findByMenuId($item['menu_id'])
                        ->exists()
                ];
                $children = static::getUserMenuTreeByParentId($userId, $item['menu_id'], $order);
                if ($children) {
                    $node['leaf'] = false;
                    $node['children'] = $children;
                } else {
                    $node['leaf'] = true;
                }
                $tree[] = $node;
            }
        }

        return $tree;
    }

public function isAssignableFrom(Type $type)
    {
        if ($type->getName() === $this->getName())
            return true;

        if (!($type instanceof ClassType))
            return false;

        return $type->isSubtypeOf($this);
    }

