public function createDir($dirname, Config $config)
    {
        $info = $this->getPathInfo($dirname);
        $status = [
            'path' => $info['path'],
            'type' => 'dir',
            'visibility' => $config->get('visibility', 'public'),
            'timestamp' => time(),
        ];

        if ( ! $this->has($info['path']))
        {
            if ( ! $this->ensurePathExists($info['dirname'], $config)
                || ! ($this->redis->hsetnx($this->applyPathPrefix($info['path']), '.', json_encode($status))
                    && $this->redis->hsetnx($this->applyPathPrefix($info['dirname']), $info['basename'], json_encode($status))))
            {
                $status = false;
            }
        }
        elseif ($this->getMetadata($info['path'])['type'] === 'file')
        {
            $status = false;
        }

        return $status;
    }

protected function parseKey($key, $and = true, $noCondition = false, $noTable = false)
    {
        $condition = '';
        $arr = explode('-', $key);
        $len = count($arr);
        for ($i = 1; $i < $len; $i += 2) {
            isset($arr[$i + 1]) && $condition .= ($condition ? ($and ? ' AND ' : ' OR ') : '') . "`{$arr[$i]}` = %s";
            $this->bindParams[] = $arr[$i + 1];
        }
        $table = strtolower($arr[0]);
        if (empty($table) && !$noTable) {
            throw new \InvalidArgumentException(Lang::get('_DB_PARAM_ERROR_PARSE_KEY_', $key, 'table'));
        }
        if (empty($condition) && !$noCondition) {
            throw new \InvalidArgumentException(Lang::get('_DB_PARAM_ERROR_PARSE_KEY_', $key, 'condition'));
        }
        empty($condition) || $condition = "($condition)";
        return [$table, $condition];
    }

