def create_from_dict(self, dictionary):
        """ Initializes an instance from a dictionary blueprint """
        # Defaults
        args = []
        kwargs = {}
        factory_method = None
        factory_args = []
        factory_kwargs = {}
        static = False
        calls = None

        # Check dictionary for arguments
        if 'args' in dictionary:
            args = dictionary['args']

        if 'kwargs' in dictionary:
            kwargs = dictionary['kwargs']

        if 'factory-method' in dictionary:
            factory_method = dictionary['factory-method']

        if 'factory-args' in dictionary:
            factory_args = dictionary['factory-args']

        if 'factory-kwargs' in dictionary:
            factory_kwargs = dictionary['factory-kwargs']

        if 'static' in dictionary:
            static = dictionary['static']

        if 'calls' in dictionary:
            calls = dictionary['calls']

        return self.create(
            dictionary['module'],
            dictionary['class'],
            args=args,
            kwargs=kwargs,
            factory_method=factory_method,
            factory_args=factory_args,
            factory_kwargs=factory_kwargs,
            static=static,
            calls=calls
        )

def track(*args):
    """
    Track additional files. It is often useful to use glob.glob here.
    For instance:

        track('config.ini', glob.glob('templates/*.pt'), glob.glob('db/*.db'))

    @param args: A list where each element is either a filename or an
        iterable of filenames
    """
    for arg in args:
        if isinstance(arg, str):
            arg = [arg]
        for filename in arg:
            realname, modified_time = _get_filename_and_modified(filename)
            if realname and realname not in _process_files:
                _process_files[realname] = modified_time

def camelise(text, capital_first=True):
    """Convert lower_underscore to CamelCase."""

    def camelcase():
        if not capital_first:
            yield str.lower
        while True:
            yield str.capitalize

    if istype(text, 'unicode'):
        text = text.encode('utf8')
    c = camelcase()
    return "".join(next(c)(x) if x else '_' for x in text.split("_"))

