def _load(self, tree):
        """ Run a LOAD statement """
        filename = tree.load_file[0]
        if filename[0] in ['"', "'"]:
            filename = unwrap(filename)
        if not os.path.exists(filename):
            raise Exception("No such file %r" % filename)
        batch = self.connection.batch_write(tree.table)
        count = 0
        with batch:
            remainder, ext = os.path.splitext(filename)
            if ext.lower() in [".gz", ".gzip"]:
                ext = os.path.splitext(remainder)[1]
                opened = gzip.open(filename, "rb")
            else:
                opened = open(filename, "r")
            with opened as ifile:
                if ext.lower() == ".csv":
                    reader = csv.DictReader(ifile)
                    for row in reader:
                        batch.put(row)
                        count += 1
                elif ext.lower() == ".json":
                    for row in ifile:
                        batch.put(json.loads(row))
                        count += 1
                else:
                    try:
                        while True:
                            batch.put(pickle.load(ifile))
                            count += 1
                    except EOFError:
                        pass
        return count

def _convert_verbal_form( analysis ):
    ''' Converts ordinary verbal categories of the input analysis. 
        Performs one-to-one conversions. '''
    assert FORM in analysis, '(!) The input analysis does not contain "'+FORM+'" key.'
    for form, replacement in _verb_conversion_rules:
        # Exact match
        if analysis[FORM] == form:
           assert analysis[POSTAG] == 'V', \
               '(!) Expected analysis of verb, but got analysis of "'+str(analysis[POSTAG])+'" instead.'
           analysis[FORM] = replacement
        # Inclusion :   the case of some_prefix+' '+form ;
        elif analysis[FORM].endswith(' '+form):
           parts  = analysis[FORM].split()
           prefix = ' '.join( parts[:len(parts)-1] )
           analysis[FORM] = prefix+' '+replacement
    return analysis

