def _get_language_description(self, language_code):
        """
        Returns the description of language.

        :param language_code: The BCP 47 code language.
        :type language_code: str
        :return: The description of language.
        :rtype: str
        """

        language = language_code.lower()
        parameter = 'language-' + language
        if self.configure.has_parameter(parameter):
            return self.configure.get_parameter(parameter)
        elif '-' in language:
            codes = re.split(r'\-', language)
            parameter = 'language-' + codes[0]
            if self.configure.has_parameter(parameter):
                return self.configure.get_parameter(parameter)
        return None

def contains_one_of(*fields):
    """Enables ensuring that one of multiple optional fields is set"""
    message = 'Must contain any one of the following fields: {0}'.format(', '.join(fields))

    def check_contains(endpoint_fields):
        for field in fields:
            if field in endpoint_fields:
                return

        errors = {}
        for field in fields:
            errors[field] = 'one of these must have a value'
        return errors
    check_contains.__doc__ = message
    return check_contains

