def _get_counts_in_1x(data_is_basepairs):
    """ Read read length and genome size from the config and calculate
        the approximate number of counts (or base pairs) in 1x of depth
    """
    read_length = float(getattr(config, 'preseq', {}).get('read_length', 0))
    genome_size = getattr(config, 'preseq', {}).get('genome_size')
    if genome_size:
        try:
            genome_size = float(genome_size)
        except ValueError:
            presets = {'hg19_genome': 2897310462,
                       'hg38_genome': 3049315783,
                       'mm10_genome': 2652783500}
            if genome_size in presets:
                genome_size = presets[genome_size]
            else:
                log.warn('The size for genome ' + genome_size + ' is unknown to MultiQC, ' +
                         'please specify it explicitly or choose one of the following: ' +
                         ', '.join(presets.keys()) + '. Falling back to molecule counts.')
                genome_size = None

    if genome_size:
        if data_is_basepairs:
            return genome_size
        elif read_length:
            return genome_size / read_length
    else:
        return None

def compute_taxes(self, precision=None):
        '''
        Returns the total amount of taxes for this line with a specific 
        number of decimals
        @param precision: int Number of decimal places
        @return: Decimal
        '''
        base = self.gross - self.total_discounts
        return quantize(sum([t.compute(base, precision) for t in self.__taxes]),
                        precision)

def ping(host, timeout=False, return_boolean=False):
    '''
    Performs an ICMP ping to a host

    .. versionchanged:: 2015.8.0
        Added support for SunOS

    CLI Example:

    .. code-block:: bash

        salt '*' network.ping archlinux.org

    .. versionadded:: 2015.5.0

    Return a True or False instead of ping output.

    .. code-block:: bash

        salt '*' network.ping archlinux.org return_boolean=True

    Set the time to wait for a response in seconds.

    .. code-block:: bash

        salt '*' network.ping archlinux.org timeout=3
    '''
    if timeout:
        if __grains__['kernel'] == 'SunOS':
            cmd = 'ping -c 4 {1} {0}'.format(timeout, salt.utils.network.sanitize_host(host))
        else:
            cmd = 'ping -W {0} -c 4 {1}'.format(timeout, salt.utils.network.sanitize_host(host))
    else:
        cmd = 'ping -c 4 {0}'.format(salt.utils.network.sanitize_host(host))
    if return_boolean:
        ret = __salt__['cmd.run_all'](cmd)
        if ret['retcode'] != 0:
            return False
        else:
            return True
    else:
        return __salt__['cmd.run'](cmd)

