def defaults
      @defaults ||= self.class.new(key | [ discriminator ].compact | reject { |property| property.lazy? }).freeze
    end

def function_type
      @out << @input.scan(/function\(/)

      skip_whitespace
      if !@input.check(/\)/)
        return false unless function_type_arguments
      end

      return false unless @input.scan(/\)/)
      @out << ")"

      skip_whitespace
      if @input.scan(/:/)
        @out << ":"
        skip_whitespace
        return false unless null_type
      end

      true
    end

def current_user(options)
      access_token = options.fetch(:access_token)
      subdomain = options.fetch(:subdomain)

      user_url = URL.new(options.merge(
        params: {
          access_token: access_token,
        },
        path: "/api/v1/profiles/me",
      )).to_s

      response = RestClient.get(
        user_url,
        accept: :json,
      )
      build_profile(
        access_token,
        subdomain,
        JSON.parse(response)["profiles"].first
      )
    end

