def raise(exception = nil)
      exception = case
      when exception == nil then StandardError.new
      when exception.is_a?(Exception) then exception
      when Exception >= exception then exception.new
      else
        Kernel.raise(TypeError, "'exception' must be nil or an instance of or descendant of Exception")
      end
      @mutex.synchronize do
        Kernel.raise(Complete) if @complete
        @complete = true
        @exception = exception
        @waiter.resume_all_indefinitely
      end
      nil
    end

def id(id)
      return (id.is_a? Fixnum or id.is_a? Integer) ? id : @column_keys.index(id)
    end

def format_holders
      @holders.uniq!
      @holders.sort!
      holders = {}
      logger.debug "Holders are: #{@holders.join(',')}"
      @holders.map { |m| holders[m] = true }
      @holders = holders
    end

def couchrest_inheritable_reader(*ivars)
      instance_reader = ivars.pop[:reader] if ivars.last.is_a?(Hash)

      ivars.each do |ivar|
        self.class_eval <<-RUBY, __FILE__, __LINE__ + 1
          def self.#{ivar}
            return @#{ivar} if self.object_id == #{self.object_id} || defined?(@#{ivar})
            ivar = superclass.#{ivar}
            return nil if ivar.nil? && !#{self}.instance_variable_defined?("@#{ivar}")
            @#{ivar} = ivar && !ivar.is_a?(Module) && !ivar.is_a?(Numeric) && !ivar.is_a?(TrueClass) && !ivar.is_a?(FalseClass) ? ivar.dup : ivar
          end
        RUBY
        unless instance_reader == false
          self.class_eval <<-RUBY, __FILE__, __LINE__ + 1
            def #{ivar}
              self.class.#{ivar}
            end
          RUBY
        end
      end
    end

def project_admin?(project = nil)
      return false unless project.is_a?(Array)
      # => parse_auth.include?(user) && parse_auth[user]['roles'].any? { |r| ['admin', project].include? r.to_s.downcase }
      auth['roles'].any? { |r| ['admin', project].include? r.to_s.downcase }
    end

