        false
      else
        @pid = Spoon.spawnp('ruby',
          File.expand_path(File.join(File.dirname(__FILE__), %w{webrick server.rb})),
          @options[:host],
          @options[:port].to_s,
          @options[:ssl].to_s,
          @options[:docroot]
        )
        wait_for_port
        if @options[:launchy]
          scheme = options[:ssl] ? "https" : "http"
