def tick
      deleted = nil
      @to_delete.each do |tuple|
        k = get_key_vals(tuple)
        k_str = MessagePack.pack(k)
        cols_str = @dbm[k_str]
        unless cols_str.nil?
          db_cols = MessagePack.unpack(cols_str)
          delete_cols = val_cols.map{|c| tuple[cols.index(c)]}
          if db_cols == delete_cols
            deleted ||= @dbm.delete k_str
          end
        end
      end
      @to_delete = []

      @invalidated = !deleted.nil?
      unless @pending.empty?
        @delta = @pending
        @pending = {}
      end
      flush
    end

def call(env)
      @env = env
      @request = Rack::Request.new(@env)
      set_locale

      @app.call(env) && return if @request.post? || @request.put? || @request.delete?

      status, headers, body = @app.call(@env)
      response = Rack::Response.new(body, status, headers)
      response.set_cookie("user-locale", value: I18n.locale, path: "/") if cookie_locale != I18n.locale.to_s
      response.finish
    end

