def dump(swf)
      @swf = swf
      @header, @swf = Swf::Header.parse(@swf)
      @tags = []
      @tags_addresses = []
      tags_length = 0
      while @header.length + tags_length < @header.file_length
        addr = @header.length + tags_length
        @tags_addresses << addr
        tag = Swf::Tag.new(@swf[addr..-1])
        tags_length += tag.length
        @tags << tag
      end
      self
    end

