def format(format = nil, *args)
      str = (format || FORMAT).dup
      .gsub(/(%[-+.\d]*)n/) { "#{$1}s" % label }
      .gsub(/(%[-+.\d]*)u/) { "#{$1}f" % utime }
      .gsub(/(%[-+.\d]*)y/) { "#{$1}f" % stime }
      .gsub(/(%[-+.\d]*)U/) { "#{$1}f" % cutime }
      .gsub(/(%[-+.\d]*)Y/) { "#{$1}f" % cstime }
      .gsub(/(%[-+.\d]*)t/) { "#{$1}f" % total }
      .gsub(/(%[-+.\d]*)r/) { "(#{$1}f)" % real }
      format ? str % args : str
    end

