def parse_ip4(ip_output)
      cidr_ip = parse_ip_output(ip_output, /inet /, 1)
      return unless cidr_ip

      parts = cidr_ip.split('/')
      @network_conf[:address] = parts[0]
      @network_conf[:prefix] = parts[1].to_i
    end
